-- 0001_extensions_and_types.sql
-- Dizkarte schema foundation: extensions, enum types, and shared helpers.
-- Idempotent where practical. Applied as a reviewed forward migration.

-- ---------------------------------------------------------------------------
-- Extensions
-- ---------------------------------------------------------------------------
create extension if not exists "pgcrypto";      -- gen_random_uuid()
create extension if not exists "citext";         -- case-insensitive email
create extension if not exists "postgis";        -- geography(Point, 4326)

-- ---------------------------------------------------------------------------
-- Application schema for privileged/internal objects that must not be exposed
-- directly through PostgREST.
-- ---------------------------------------------------------------------------
create schema if not exists app;

-- RLS policy predicates and the helper functions used by policies live in the
-- `app` schema. The Supabase API roles need USAGE on the schema to invoke them
-- (per-function EXECUTE is still controlled individually, and `app` is never
-- added to PostgREST's exposed schemas, so this does not expose anything via
-- the REST API). Without this grant, any RLS policy that calls `app.*` fails at
-- query time with "permission denied for schema app".
grant usage on schema app to anon, authenticated, service_role;

-- ---------------------------------------------------------------------------
-- Enum types. Values mirror @dizkarte/domain status unions exactly.
-- ---------------------------------------------------------------------------
do $$
begin
  if not exists (select 1 from pg_type where typname = 'account_status') then
    create type account_status as enum ('active', 'suspended', 'banned', 'deactivated');
  end if;

  if not exists (select 1 from pg_type where typname = 'user_capability') then
    create type user_capability as enum
      ('CLIENT', 'TASKER', 'ADMIN_SUPPORT', 'ADMIN_FINANCE', 'ADMIN_SUPER');
  end if;

  if not exists (select 1 from pg_type where typname = 'verification_status') then
    create type verification_status as enum
      ('DRAFT', 'SUBMITTED', 'IN_REVIEW', 'APPROVED', 'REJECTED', 'RESUBMISSION_REQUIRED');
  end if;

  if not exists (select 1 from pg_type where typname = 'tasker_application_status') then
    create type tasker_application_status as enum
      ('DRAFT', 'SUBMITTED', 'IN_REVIEW', 'APPROVED', 'REJECTED', 'RESUBMISSION_REQUIRED', 'SUSPENDED');
  end if;

  if not exists (select 1 from pg_type where typname = 'task_status') then
    create type task_status as enum
      ('DRAFT', 'OPEN', 'BOOKING_PENDING', 'ASSIGNED', 'IN_PROGRESS',
       'COMPLETION_REQUESTED', 'COMPLETED', 'EXPIRED', 'CANCELLED', 'DISPUTED', 'REMOVED');
  end if;

  if not exists (select 1 from pg_type where typname = 'offer_status') then
    create type offer_status as enum
      ('SUBMITTED', 'SELECTED', 'WITHDRAWN', 'REJECTED', 'EXPIRED');
  end if;

  if not exists (select 1 from pg_type where typname = 'booking_status') then
    create type booking_status as enum
      ('PAYMENT_PENDING', 'CONFIRMED', 'IN_PROGRESS', 'COMPLETION_REQUESTED',
       'COMPLETED', 'PAYMENT_FAILED', 'CANCELLED', 'DISPUTED', 'REFUNDED');
  end if;

  if not exists (select 1 from pg_type where typname = 'payment_status') then
    create type payment_status as enum ('CREATED', 'PENDING', 'CONFIRMED', 'FAILED');
  end if;

  if not exists (select 1 from pg_type where typname = 'withdrawal_status') then
    create type withdrawal_status as enum
      ('REQUESTED', 'RESERVED', 'PROCESSING', 'PAID', 'FAILED', 'CANCELLED');
  end if;

  if not exists (select 1 from pg_type where typname = 'review_status') then
    create type review_status as enum ('HIDDEN', 'REVEALED', 'MODERATED');
  end if;

  if not exists (select 1 from pg_type where typname = 'dispute_status') then
    create type dispute_status as enum ('OPEN', 'UNDER_REVIEW', 'RESOLVED', 'REJECTED', 'CANCELLED');
  end if;

  if not exists (select 1 from pg_type where typname = 'report_status') then
    create type report_status as enum ('OPEN', 'TRIAGED', 'ACTIONED', 'DISMISSED');
  end if;

  if not exists (select 1 from pg_type where typname = 'ticket_status') then
    create type ticket_status as enum ('OPEN', 'PENDING', 'RESOLVED', 'CLOSED');
  end if;

  if not exists (select 1 from pg_type where typname = 'moderation_status') then
    create type moderation_status as enum ('PENDING', 'APPROVED', 'REJECTED', 'HIDDEN');
  end if;

  if not exists (select 1 from pg_type where typname = 'refund_status') then
    create type refund_status as enum ('REQUESTED', 'PROCESSING', 'SUCCEEDED', 'FAILED');
  end if;

  if not exists (select 1 from pg_type where typname = 'provider_event_status') then
    create type provider_event_status as enum ('RECEIVED', 'PROCESSED', 'DUPLICATE', 'QUARANTINED');
  end if;

  if not exists (select 1 from pg_type where typname = 'notification_delivery_status') then
    create type notification_delivery_status as enum ('PENDING', 'SENT', 'FAILED', 'SUPPRESSED');
  end if;

  if not exists (select 1 from pg_type where typname = 'ledger_account_type') then
    create type ledger_account_type as enum
      ('CLIENT_FUNDING', 'PROTECTED_HOLD', 'TASKER_AVAILABLE',
       'PLATFORM_FEE', 'PAYOUT_CLEARING', 'REFUND_CLEARING');
  end if;

  if not exists (select 1 from pg_type where typname = 'ledger_transaction_type') then
    create type ledger_transaction_type as enum
      ('PAYMENT_CAPTURE', 'RELEASE_TO_TASKER', 'FEE_CHARGE', 'REFUND',
       'WITHDRAWAL_RESERVE', 'WITHDRAWAL_SETTLE', 'WITHDRAWAL_REVERSE', 'FREEZE', 'UNFREEZE');
  end if;
end
$$;

-- ---------------------------------------------------------------------------
-- Shared helper functions
-- ---------------------------------------------------------------------------

-- Generic updated_at trigger.
create or replace function app.set_updated_at()
returns trigger
language plpgsql
as $$
begin
  new.updated_at := now();
  return new;
end;
$$;

-- NOTE: the capability/admin helper functions (app.current_capabilities,
-- app.has_capability, app.is_admin) are defined at the END of
-- 0002_identity_profiles.sql, because as `language sql` functions PostgreSQL
-- validates their bodies at creation time and they read public.user_capabilities
-- and public.profiles, which are created in 0002. Defining them here (before
-- those tables exist) fails with "relation does not exist" during migration.


-- ===================================================================
-- 0002_identity_profiles.sql
-- ===================================================================

-- 0002_identity_profiles.sql
-- Identity, profile, capabilities, verification, and devices.

-- ---------------------------------------------------------------------------
-- profiles: one row per auth user. Application data separate from auth.users.
-- ---------------------------------------------------------------------------
create table if not exists public.profiles (
  id             uuid primary key references auth.users(id) on delete cascade,
  display_name   text not null check (char_length(display_name) between 2 and 80),
  avatar_path    text,
  mobile         text,
  city_code      text,
  barangay_code  text,
  language       text not null default 'en' check (language in ('en', 'fil')),
  bio            text check (bio is null or char_length(bio) <= 2000),
  account_status account_status not null default 'active',
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now()
);

drop trigger if exists trg_profiles_updated_at on public.profiles;
create trigger trg_profiles_updated_at
  before update on public.profiles
  for each row execute function app.set_updated_at();

-- ---------------------------------------------------------------------------
-- user_capabilities: server-granted roles. Users cannot write this table.
-- ---------------------------------------------------------------------------
create table if not exists public.user_capabilities (
  id          uuid primary key default gen_random_uuid(),
  user_id     uuid not null references public.profiles(id) on delete cascade,
  capability  user_capability not null,
  granted_at  timestamptz not null default now(),
  granted_by  uuid references public.profiles(id),
  revoked_at  timestamptz,
  revoked_by  uuid references public.profiles(id)
);

-- One active grant per (user, capability).
create unique index if not exists uq_user_capability_active
  on public.user_capabilities (user_id, capability)
  where revoked_at is null;

create index if not exists ix_user_capabilities_user on public.user_capabilities (user_id);

-- ---------------------------------------------------------------------------
-- verification_cases: identity verification lifecycle.
-- ---------------------------------------------------------------------------
create table if not exists public.verification_cases (
  id               uuid primary key default gen_random_uuid(),
  user_id          uuid not null references public.profiles(id) on delete cascade,
  status           verification_status not null default 'DRAFT',
  version          integer not null default 1 check (version >= 1),
  submitted_at     timestamptz,
  decided_at       timestamptz,
  decided_by       uuid references public.profiles(id),
  decision_reason  text check (decision_reason is null or char_length(decision_reason) <= 1000),
  assigned_admin_id uuid references public.profiles(id),
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now()
);

-- Only one non-terminal (active) case per user at a time.
create unique index if not exists uq_verification_active_case
  on public.verification_cases (user_id)
  where status in ('DRAFT', 'SUBMITTED', 'IN_REVIEW', 'RESUBMISSION_REQUIRED');

create index if not exists ix_verification_cases_status on public.verification_cases (status);

drop trigger if exists trg_verification_cases_updated_at on public.verification_cases;
create trigger trg_verification_cases_updated_at
  before update on public.verification_cases
  for each row execute function app.set_updated_at();

create table if not exists public.verification_documents (
  id          uuid primary key default gen_random_uuid(),
  case_id     uuid not null references public.verification_cases(id) on delete cascade,
  kind        text not null check (kind in ('government_id_front', 'government_id_back', 'selfie')),
  storage_path text not null,
  mime_type   text not null check (mime_type in ('image/jpeg', 'image/png', 'application/pdf')),
  size_bytes  bigint not null check (size_bytes > 0 and size_bytes <= 10485760),
  created_at  timestamptz not null default now()
);

create index if not exists ix_verification_documents_case on public.verification_documents (case_id);

-- Immutable audit trail of verification status changes.
create table if not exists public.verification_events (
  id          uuid primary key default gen_random_uuid(),
  case_id     uuid not null references public.verification_cases(id) on delete cascade,
  from_status verification_status,
  to_status   verification_status not null,
  actor_id    uuid references public.profiles(id),
  reason      text,
  created_at  timestamptz not null default now()
);

create index if not exists ix_verification_events_case on public.verification_events (case_id, created_at);

-- ---------------------------------------------------------------------------
-- devices: push registration. Token stored as a reference/hash, never raw.
-- ---------------------------------------------------------------------------
create table if not exists public.devices (
  id             uuid primary key default gen_random_uuid(),
  user_id        uuid not null references public.profiles(id) on delete cascade,
  platform       text not null check (platform in ('ios', 'android')),
  token_reference text not null,
  enabled        boolean not null default true,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now(),
  unique (user_id, token_reference)
);

drop trigger if exists trg_devices_updated_at on public.devices;
create trigger trg_devices_updated_at
  before update on public.devices
  for each row execute function app.set_updated_at();


-- ---------------------------------------------------------------------------
-- Capability / admin helper functions (moved here from 0001).
-- These are `language sql` SECURITY DEFINER helpers whose bodies read
-- public.user_capabilities and public.profiles, so they must be created AFTER
-- those tables (defined above in this migration). PostgreSQL validates SQL
-- function bodies at creation time, so defining them in 0001 failed with
-- "relation public.user_capabilities does not exist".
-- ---------------------------------------------------------------------------

-- Returns the set of capabilities for the current authenticated user.
-- SECURITY DEFINER so RLS policies can call it without exposing the table.
create or replace function app.current_capabilities()
returns user_capability[]
language sql
stable
security definer
set search_path = public, app
as $$
  select coalesce(array_agg(uc.capability), '{}')
  from public.user_capabilities uc
  where uc.user_id = auth.uid()
    and uc.revoked_at is null;
$$;

-- True when the current user holds any of the given capabilities.
create or replace function app.has_capability(caps user_capability[])
returns boolean
language sql
stable
security definer
set search_path = public, app
as $$
  select exists (
    select 1
    from public.user_capabilities uc
    where uc.user_id = auth.uid()
      and uc.revoked_at is null
      and uc.capability = any(caps)
  );
$$;

-- True when the current user is any active Admin.
create or replace function app.is_admin()
returns boolean
language sql
stable
security definer
set search_path = public, app
as $$
  select exists (
    select 1
    from public.user_capabilities uc
    join public.profiles p on p.id = uc.user_id
    where uc.user_id = auth.uid()
      and uc.revoked_at is null
      and uc.capability in ('ADMIN_SUPPORT', 'ADMIN_FINANCE', 'ADMIN_SUPER')
      and p.account_status = 'active'
  );
$$;


