insert into public.task_question_definitions
  (category_id, code, label, input_kind, options, placeholder, required, sort_order)
select c.id, s.code, s.label, s.input_kind, s.options, s.placeholder, s.required, s.sort_order
from seed s
join public.categories c on c.slug = s.cat_slug
on conflict (category_id, code) do update
  set label       = excluded.label,
      input_kind  = excluded.input_kind,
      options     = excluded.options,
      placeholder = excluded.placeholder,
      required    = excluded.required,
      sort_order  = excluded.sort_order,
      active      = true;


-- ===================================================================
-- 0039_task_time_of_day.sql
-- ===================================================================

-- 0039_task_time_of_day.sql
--
-- Persist the coarse time of day a task is needed.
--
-- The posting wizard already asks "I need a certain time of day" and offers
-- Morning / Midday / Afternoon / Evening, but the choice was only ever held in
-- screen-local state: it was discarded on submit, so a Client who asked for a
-- morning job had that requirement silently dropped and Taskers quoted without
-- it. This adds a first-class, nullable column so the answer survives the
-- round-trip and can be shown back on the task.
--
-- NULL is meaningful and is the default: it means the Client is flexible about
-- the time within the day, which is exactly the state of every task posted
-- before this column existed.
--
-- SAFETY: purely additive. No existing column, row, trigger, policy, view, or
-- RPC is altered — `scheduled_for` and `same_day` keep their current meaning,
-- and the public feed/search contracts are unchanged. Every statement is
-- idempotent so re-running the migration is a no-op. Table-level privileges
-- granted in 0014 already cover new columns, so `authenticated` can read/write
-- this one under the existing RLS row gate.

alter table public.tasks
  add column if not exists time_of_day text;

-- Mirrors `taskTimeOfDaySchema` in @dizkarte/domain, so an invalid slot can
-- never be stored even if a caller bypasses the client. Only constrains the
-- value when one is set; a flexible task keeps it NULL. Dropped-then-added so
-- the migration stays re-runnable.
alter table public.tasks
  drop constraint if exists tasks_time_of_day_check;
alter table public.tasks
  add constraint tasks_time_of_day_check
  check (time_of_day is null or time_of_day in ('morning', 'midday', 'afternoon', 'evening'));


-- ===================================================================
-- 0040_cancel_own_task.sql
-- ===================================================================

-- 0040_cancel_own_task.sql
--
-- Let a Client cancel their own task before it carries any booking.
--
-- The task lifecycle (`packages/domain/src/state/task.ts`) has always allowed
-- DRAFT -> CANCELLED and OPEN -> CANCELLED, and Admins can already remove a task
-- via `admin_moderate_task` (0016). The task's own owner could not: 0009 gives
-- `public.tasks` an owner UPDATE policy for editing a draft, but the marketplace
-- had no command to retire a task, so a Client who no longer needed a job had to
-- leave it open and let Taskers keep quoting on it.
--
-- SCOPE — deliberately pre-payment only. This command refuses any state from
-- BOOKING_PENDING onward, because once an offer has been selected there is money
-- or a commitment attached and the outcome depends on the cancellation/refund
-- policy that is still an open decision (register D13). Abandoning an unpaid
-- booking already has its own narrow path (`cancel_unpaid_booking`, 0027), and
-- anything further belongs to the dispute/refund flow. Nothing here invents a
-- penalty, a fee, or a refund.
--
-- A broad owner UPDATE of `status` would be the wrong fix: it would let a Client
-- move a task into any state, including ones that imply payment. This is a
-- narrow SECURITY DEFINER command that can only ever move DRAFT/OPEN ->
-- CANCELLED for the caller's own task, and it locks the task row first so it
-- cannot interleave with `select_offer`.

create or replace function public.cancel_own_task(
  p_task_id uuid,
  p_idempotency_key text
)
returns public.tasks
language plpgsql
security definer
set search_path = public, app
as $$
declare
  v_task  public.tasks;
  v_offer public.offers;
begin
  if p_idempotency_key is null or btrim(p_idempotency_key) = ''
     or char_length(p_idempotency_key) > 200 then
    raise exception 'VALIDATION_ERROR: a non-empty idempotency key (1..200 chars) is required.'
      using errcode = 'check_violation';
  end if;

  select * into v_task from public.tasks where id = p_task_id;
  if not found then
    raise exception 'NOT_FOUND: task' using errcode = 'no_data_found';
  end if;

  -- Only the owning Client may cancel, and only on an active account.
  if v_task.client_id <> auth.uid() then
    raise exception 'FORBIDDEN: only the task owner may cancel this task.'
      using errcode = 'insufficient_privilege';
  end if;
  if not app.is_active_account() then
    raise exception 'FORBIDDEN: account is not active.' using errcode = 'insufficient_privilege';
  end if;

  -- Idempotent: cancelling an already-cancelled task is a no-op success.
  if v_task.status = 'CANCELLED' then
    return v_task;
  end if;

  -- Lock the task so this cannot interleave with an offer being selected, then
  -- re-read under that lock before deciding.
  select * into v_task from public.tasks where id = p_task_id for update;

  if v_task.status = 'CANCELLED' then
    return v_task;
  end if;
  if v_task.status not in ('DRAFT', 'OPEN') then
    raise exception 'INVALID_STATE: only a draft or open task with no booking can be cancelled (current: %).', v_task.status
      using errcode = 'check_violation';
  end if;

  update public.tasks
    set status = 'CANCELLED', updated_at = now()
    where id = p_task_id
    returning * into v_task;

  -- Every still-live offer is now moot. Rejecting them keeps offer state honest
  -- (no Tasker is left believing they are still in the running) and records the
  -- transition in the offer's own history, the same way selection does.
  for v_offer in
    select * from public.offers
    where task_id = p_task_id and status = 'SUBMITTED'
    for update
  loop
    update public.offers
      set status = 'REJECTED', updated_at = now()
      where id = v_offer.id;

    insert into public.offer_events (offer_id, actor_id, event_type, metadata)
    values (v_offer.id, auth.uid(), 'rejected',
            jsonb_build_object('idempotency_key', p_idempotency_key,
                               'reason', 'task_cancelled_by_client'));

    -- Best-effort courtesy notice; app.notify already no-ops silently if the
    -- recipient muted the category, so it can never fail the cancellation.
    perform app.notify(
      v_offer.tasker_id,
      'TASK_CANCELLED',
      'A task you offered on was cancelled',
      format('The client cancelled "%s", so your offer was closed.',
             coalesce(v_task.title, 'a task')),
      'task',
      p_task_id
    );
  end loop;

  insert into public.audit_logs (actor_id, action, resource_type, resource_id, safe_metadata)
  values (auth.uid(), 'task.cancelled_by_owner', 'task', p_task_id,
          jsonb_build_object('idempotency_key', p_idempotency_key,
                             'from_status', 'DRAFT_OR_OPEN'));

  return v_task;
end;
$$;

grant execute on function public.cancel_own_task(uuid, text) to authenticated;


-- ===================================================================
-- 0041_task_location_type_and_dropoff.sql
-- ===================================================================

-- 0041_task_location_type_and_dropoff.sql
--
-- Two additive fields the posting flow already collected but could not store.
--
-- 1. `tasks.location_type` — the wizard has always offered "In Person" vs
--    "Online", but the choice only ever existed in screen-local state. The sole
--    trace of a remote task was the literal string "Online / Remote" written
--    into the public `landmark`, so nothing could distinguish a genuinely remote
--    task from one whose landmark happened to read that way, and the choice was
--    lost on reload. This makes it a real, queryable field.
--
--    An online task still records a city/barangay: the locality is what makes a
--    task discoverable regionally and `task_public_locations` requires it. What
--    the flag changes is the meaning — for a remote task the locality is where
--    the Client is, not where the Tasker must appear.
--
-- 2. `task_public_locations.dropoff_landmark` — the wizard asks removals Clients
--    for a drop-off location and then discarded it on submit. It is stored at
--    the same public, area-level precision as `landmark` and is NEVER an exact
--    address: `task_public_locations` is readable by any authenticated user
--    through the public feed, so a second precise address here would defeat the
--    approximate/exact separation that requirement R4 exists to protect. If an
--    exact drop-off is ever needed it belongs beside `exact_address` in
--    `task_private_locations`, behind the confirmed-booking gate.
--
-- SAFETY: purely additive and idempotent. Both columns are nullable with
-- sensible reads for existing rows (`location_type` defaults to 'in_person',
-- which is what every task posted before this was; `dropoff_landmark` stays
-- NULL, meaning "single location"). No existing column, row, trigger, policy, or
-- RPC changes behaviour, and the public feed view is untouched. Table-level
-- privileges from 0014 already cover new columns.

-- 1. Task location type ------------------------------------------------------

alter table public.tasks
  add column if not exists location_type text not null default 'in_person';

-- Mirrors `taskLocationTypeSchema` in @dizkarte/domain so an invalid value can
-- never be stored even if a caller bypasses the client. Dropped-then-added so
-- the migration stays re-runnable.
alter table public.tasks
  drop constraint if exists tasks_location_type_check;
alter table public.tasks
  add constraint tasks_location_type_check
  check (location_type in ('in_person', 'online'));

-- 2. Public, area-level drop-off ---------------------------------------------

alter table public.task_public_locations
  add column if not exists dropoff_landmark text;

alter table public.task_public_locations
  drop constraint if exists task_public_locations_dropoff_landmark_check;
alter table public.task_public_locations
  add constraint task_public_locations_dropoff_landmark_check
  check (dropoff_landmark is null or char_length(dropoff_landmark) between 1 and 200);

-- 3. Expose the drop-off through the coordinate-readable view -----------------
--
-- Recreated from 0017 with the one new column **appended last**. That ordering
-- is required, not cosmetic: `create or replace view` may only add columns at
-- the end of the select list, and inserting `dropoff_landmark` before
-- `approximate_lat` fails with "cannot change name of view column". Still
-- `security_invoker = true`, so the caller's own RLS on
-- `task_public_locations` continues to decide visibility — the view grants no
-- additional access, and the drop-off is exactly as public as the landmark
-- beside it.
create or replace view public.task_locations_readable
with (security_invoker = true)
as
select
  pl.task_id,
  pl.city_code,
  pl.barangay_code,
  pl.landmark,
  round(st_y(pl.approximate_point::geometry)::numeric, 3) as approximate_lat,
  round(st_x(pl.approximate_point::geometry)::numeric, 3) as approximate_lng,
  pl.dropoff_landmark
from public.task_public_locations pl;

grant select on public.task_locations_readable to authenticated;


-- ===================================================================
-- 0042_review_aggregate_on_reveal.sql
-- ===================================================================

-- 0042_review_aggregate_on_reveal.sql
-- Stop a still-hidden review from moving the Tasker's PUBLIC rating.
--
-- Requirement R10 / the Milestone 3 exit gate say a review stays secret until
-- both participants submit or the review window expires. The review TEXT was
-- correctly withheld, but the SCORE was not: `submit_review` (0011) incremented
-- `tasker_profiles.rating_sum` / `rating_count` at insert time, while the row was
-- still `HIDDEN`, and `public_tasker_profiles.rating_average` (0008) is derived
-- from exactly those two columns. Anyone browsing offers could therefore watch a
-- Tasker's average move — and, with `rating_count` visible, infer that a review
-- had landed and roughly what it said — before the blind window closed.
--
-- Fix: the aggregate counts REVEALED reviews only, and is RECOMPUTED from the
-- rows rather than nudged by deltas.
--
--   * Recompute is idempotent. The previous delta arithmetic had to be applied
--     exactly once per event, which is why 0023 needed `greatest(0, ...)` guards
--     and an idempotency check to avoid double-applying a moderation. A
--     recount cannot drift, double-count, or go negative.
--   * Every reveal path now converges on one function, so a future reveal path
--     cannot forget to update the aggregate.
--
-- Touched functions: `submit_review` (0011), `get_review_pair` (0021, the lazy
-- expiry reveal), `admin_moderate_review` (0023). Their contracts, authorization,
-- and error codes are unchanged; only aggregate maintenance moves.

-- ---------------------------------------------------------------------------
-- app.recount_review_aggregate — the single source of a reviewee's aggregate.
--
-- REVEALED only: HIDDEN (blind window still open) and MODERATED (withdrawn by an
-- Admin) rows are excluded. A reviewee with no revealed reviews lands on 0/0,
-- which `public_tasker_profiles` renders as a null average, not "0 stars".
--
-- Written for a Client reviewee too: they have no `tasker_profiles` row, so the
-- UPDATE simply matches nothing. That is the pre-existing asymmetry (only
-- Taskers carry a public rating), made explicit rather than silently relied on.
-- ---------------------------------------------------------------------------
create or replace function app.recount_review_aggregate(p_user_id uuid)
returns void
language sql
security definer
set search_path = public, app
as $$
  update public.tasker_profiles tp
     set rating_sum   = coalesce(agg.total, 0),
         rating_count = coalesce(agg.entries, 0)
    from (
      select sum(r.score)::integer as total,
             count(*)::integer     as entries
      from public.reviews r
      where r.reviewee_id = p_user_id
        and r.status = 'REVEALED'
    ) agg
   where tp.user_id = p_user_id
     and (tp.rating_sum <> coalesce(agg.total, 0)
       or tp.rating_count <> coalesce(agg.entries, 0));
$$;

revoke execute on function app.recount_review_aggregate(uuid)
  from public, anon, authenticated, service_role;

-- ---------------------------------------------------------------------------
-- submit_review — unchanged contract, aggregate no longer moves at insert.
-- ---------------------------------------------------------------------------
create or replace function public.submit_review(
  p_booking_id uuid, p_score integer, p_comment text
)
returns public.reviews
language plpgsql
security definer
set search_path = public, app
as $$
declare
  v_booking public.bookings;
  v_reviewee uuid;
  v_review public.reviews;
  v_both boolean;
  v_target uuid;
begin
  select * into v_booking from public.bookings where id = p_booking_id;
  if not found then raise exception 'NOT_FOUND: booking' using errcode = 'no_data_found'; end if;
  if v_booking.status <> 'COMPLETED' then
    raise exception 'INVALID_STATE: reviews require a completed booking.' using errcode = 'check_violation';
  end if;
  if auth.uid() = v_booking.client_id then
    v_reviewee := v_booking.tasker_id;
  elsif auth.uid() = v_booking.tasker_id then
    v_reviewee := v_booking.client_id;
  else
    raise exception 'FORBIDDEN: only participants may review.' using errcode = 'insufficient_privilege';
  end if;

  insert into public.reviews (booking_id, reviewer_id, reviewee_id, score, comment, status)
  values (p_booking_id, auth.uid(), v_reviewee, p_score, p_comment, 'HIDDEN')
  returning * into v_review;

  -- Reveal both when both participants have reviewed.
  select count(*) = 2 into v_both from public.reviews where booking_id = p_booking_id;
  if v_both then
    update public.reviews set status = 'REVEALED', revealed_at = now()
      where booking_id = p_booking_id and status = 'HIDDEN';
    -- Re-read so the caller's own row carries the revealed state it now has.
    select * into v_review from public.reviews where id = v_review.id;
  end if;

  -- Aggregate maintenance: recount both participants from REVEALED rows only.
  -- Unconditional because it is idempotent — and because running it on the
  -- HIDDEN path is precisely what keeps the public average from moving early.
  for v_target in
    select distinct r.reviewee_id from public.reviews r where r.booking_id = p_booking_id
  loop
    perform app.recount_review_aggregate(v_target);
  end loop;

  return v_review;
exception
  when unique_violation then
    raise exception 'CONFLICT: you have already reviewed this booking.' using errcode = 'unique_violation';
end;
$$;

-- ---------------------------------------------------------------------------
-- get_review_pair — the lazy expiry reveal now also publishes the score.
--
-- Identical to 0021 except that a reveal performed here recounts the aggregate
-- of every reviewee whose row it just revealed. Without this, a one-sided review
-- that reveals on expiry would become readable while still absent from the
-- public average — the mirror image of the defect above.
-- ---------------------------------------------------------------------------
create or replace function public.get_review_pair(p_booking_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = public, app
as $$
declare
  v_booking  public.bookings;
  v_first    timestamptz;
  v_count    integer;
  v_deadline timestamptz;
  v_mine     public.reviews;
  v_other    public.reviews;
  v_has_mine boolean := false;
  v_has_other boolean := false;
  v_target   uuid;
  v_revealed boolean := false;
begin
  if auth.uid() is null then
    raise exception 'FORBIDDEN: authentication is required.'
      using errcode = 'insufficient_privilege';
  end if;

  select * into v_booking from public.bookings where id = p_booking_id;
  if not found then
    raise exception 'NOT_FOUND: booking %', p_booking_id using errcode = 'no_data_found';
  end if;
  if auth.uid() <> v_booking.client_id and auth.uid() <> v_booking.tasker_id then
    raise exception 'FORBIDDEN: only booking participants may read its reviews.'
      using errcode = 'insufficient_privilege';
  end if;

  select min(submitted_at), count(*) into v_first, v_count
  from public.reviews where booking_id = p_booking_id;

  if v_first is not null then
    v_deadline := v_first + make_interval(days => app.review_reveal_days());
  end if;

  if v_count >= 2 or (v_deadline is not null and v_deadline <= now()) then
    update public.reviews
       set status = 'REVEALED',
           revealed_at = coalesce(revealed_at, now())
     where booking_id = p_booking_id and status = 'HIDDEN';
    v_revealed := found;
  end if;

  if v_revealed then
    for v_target in
      select distinct r.reviewee_id from public.reviews r where r.booking_id = p_booking_id
    loop
      perform app.recount_review_aggregate(v_target);
    end loop;
  end if;

  select * into v_mine
  from public.reviews
  where booking_id = p_booking_id and reviewer_id = auth.uid();
  v_has_mine := found;

  select * into v_other
  from public.reviews
  where booking_id = p_booking_id and reviewer_id <> auth.uid();
  v_has_other := found;

  return jsonb_build_object(
    'booking_id', p_booking_id,
    'reveal_deadline', v_deadline,
    'both_submitted', v_count >= 2,
    'my_review', case when v_has_mine then to_jsonb(v_mine) else null end,
    'counterpart_review',
      case when v_has_other and v_other.status = 'REVEALED'
           then to_jsonb(v_other) else null end
  );
end;
$$;

grant execute on function public.get_review_pair(uuid) to authenticated;

-- ---------------------------------------------------------------------------
-- admin_moderate_review — delta arithmetic replaced by the recount.
--
-- The idempotency check stays (it still guards the audit/moderation rows), but
-- the aggregate no longer depends on it for correctness.
-- ---------------------------------------------------------------------------
create or replace function public.admin_moderate_review(
  p_review_id uuid,
  p_action text,
  p_reason text,
  p_idempotency_key text
)
returns public.reviews
language plpgsql
security definer
set search_path = public, app
as $$
declare
  v_row public.reviews;
  v_cap user_capability;
begin
  perform app.assert_reasoned(p_reason, p_idempotency_key);
  v_cap := app.acting_capability(array['ADMIN_SUPPORT','ADMIN_SUPER']::user_capability[]);
  if v_cap is null then
    raise exception 'FORBIDDEN: review moderation requires an active support/super Admin.'
      using errcode = 'insufficient_privilege';
  end if;
  if p_action not in ('hide','restore') then
    raise exception 'INVALID_STATE: unsupported moderation action %', p_action
      using errcode = 'check_violation';
  end if;

  select * into v_row from public.reviews where id = p_review_id for update;
  if not found then raise exception 'NOT_FOUND: review' using errcode = 'no_data_found'; end if;

  if exists (select 1 from public.moderation_actions ma
             where ma.resource_type = 'review' and ma.resource_id = p_review_id
               and ma.admin_id = auth.uid()
               and ma.metadata->>'idempotency_key' = p_idempotency_key) then
    return v_row;
  end if;

  if p_action = 'hide' then
    if v_row.status = 'MODERATED' then return v_row; end if;
    update public.reviews set status = 'MODERATED' where id = p_review_id returning * into v_row;
  else
    if v_row.status <> 'MODERATED' then return v_row; end if;
    -- A review that was never revealed goes back to HIDDEN, not REVEALED: the
    -- blind window is the counterpart's, not the Admin's, to end. Restoring to
    -- HIDDEN therefore also keeps it out of the aggregate.
    --
    -- The explicit casts matter: with two bare literals the CASE resolves to
    -- `text`, and there is no implicit text→review_status cast, so this statement
    -- failed at runtime. That defect shipped in 0023 and went unnoticed because
    -- no test ever exercised `restore`; it is fixed here and now covered by
    -- `supabase/tests/milestone3_reviews_notifications.sql`.
    update public.reviews
       set status = case
             when v_row.revealed_at is null then 'HIDDEN'::review_status
             else 'REVEALED'::review_status
           end
     where id = p_review_id
    returning * into v_row;
  end if;

  perform app.recount_review_aggregate(v_row.reviewee_id);

  insert into public.moderation_actions (admin_id, capability, resource_type, resource_id, action, reason, metadata)
  values (auth.uid(), v_cap, 'review', p_review_id, p_action, p_reason,
          jsonb_build_object('idempotency_key', p_idempotency_key, 'to_status', v_row.status));
  insert into public.audit_logs (actor_id, action, resource_type, resource_id, safe_metadata)
  values (auth.uid(), 'admin.review.' || p_action, 'review', p_review_id,
          jsonb_build_object('capability', v_cap, 'to_status', v_row.status,
                             'idempotency_key', p_idempotency_key));

  return v_row;
end;
$$;

grant execute on function public.admin_moderate_review(uuid, text, text, text) to authenticated;

-- ---------------------------------------------------------------------------
-- One-time correction of aggregates written under the old rule.
--
-- Any average that currently includes a HIDDEN review is wrong from this point
-- on, so it is recomputed here rather than left to drift until the next review.
-- ---------------------------------------------------------------------------
update public.tasker_profiles tp
   set rating_sum   = coalesce(agg.total, 0),
       rating_count = coalesce(agg.entries, 0)
  from (
    select p.user_id,
           (select sum(r.score)::integer from public.reviews r
             where r.reviewee_id = p.user_id and r.status = 'REVEALED') as total,
           (select count(*)::integer from public.reviews r
             where r.reviewee_id = p.user_id and r.status = 'REVEALED') as entries
    from public.tasker_profiles p
  ) agg
 where agg.user_id = tp.user_id
   and (tp.rating_sum <> coalesce(agg.total, 0)
     or tp.rating_count <> coalesce(agg.entries, 0));


-- ===================================================================
-- 0043_notification_producers.sql
-- ===================================================================

-- 0043_notification_producers.sql
-- Produce the two Phase 3 notifications that had no producer.
--
-- Wave 3B requires push/in-app delivery "for offers, bookings, messages, payment
-- states, REVIEW REMINDERS, and approved NEARBY ALERTS". The first four were
-- emitted by the 0020 triggers, but:
--
--   * REVIEW_REMINDER did not exist at all. `BOOKING_COMPLETED` carries a
--     one-time "leave a review" line, and after that nothing ever reminded a
--     participant, so the blind review window could expire in silence.
--   * The `nearby` PREFERENCE category was added by 0031, but no code ever wrote
--     a nearby notification — the toggle governed nothing.
--
-- Both are added here with the same discipline as 0020: `app.notify` is the only
-- insert path (so the recipient's category preference is always honoured), and
-- nothing raises into the caller's transaction.
--
-- Delivery-channel note: these two types are also mapped in
-- `packages/domain/src/adapters/push-delivery.ts` and in the `push-dispatch`
-- edge function. The three mappings must agree, or a user who muted a category
-- in-app would still receive it as a push.

-- ---------------------------------------------------------------------------
-- Preference category for the two new types.
--
-- Restated in full (rather than patched) because `app.notification_category` is
-- an immutable SQL function — there is no partial replacement.
--
-- `COMPLETION_REMINDER` is mapped here too; its producer arrives in 0044.
-- ---------------------------------------------------------------------------
create or replace function app.notification_category(p_type text)
returns text
language sql
immutable
as $$
  select case p_type
    when 'OFFER_RECEIVED'         then 'offers'
    when 'OFFER_SELECTED'         then 'offers'
    when 'PAYMENT_CONFIRMED'      then 'payments'
    when 'PAYMENT_FAILED'         then 'payments'
    when 'BOOKING_STARTED'        then 'bookings'
    when 'COMPLETION_REQUESTED'   then 'bookings'
    when 'COMPLETION_REMINDER'    then 'bookings'
    when 'BOOKING_COMPLETED'      then 'bookings'
    when 'DISPUTE_OPENED'         then 'disputes'
    when 'REVIEW_RECEIVED'        then 'reviews'
    when 'REVIEW_REMINDER'        then 'reviews'
    when 'MESSAGE_RECEIVED'       then 'messages'
    when 'VERIFICATION_DECISION'  then 'verification'
    when 'NEARBY_TASK'            then 'nearby'
    else 'system'
  end;
$$;

-- ---------------------------------------------------------------------------
-- Settings that govern the two producers.
--
-- Both are bounded and Admin-editable through `admin_update_setting` (0032)
-- only if that function's allow-list is extended; until then they are defaults
-- that a DB-admin can change deliberately. They are NOT policy decisions about
-- money, so no Client approval gate applies (contrast: auto-release, D13).
-- ---------------------------------------------------------------------------
insert into public.app_settings (key, typed_value)
values ('review_reminder_after_hours', '24'::jsonb),
       ('nearby_alert_max_recipients', '200'::jsonb)
on conflict (key) do nothing;

create or replace function app.review_reminder_after_hours()
returns integer
language sql
stable
as $$
  select greatest(1, coalesce(
    (select (typed_value #>> '{}')::integer
     from public.app_settings where key = 'review_reminder_after_hours'),
    24));
$$;

create or replace function app.nearby_alert_max_recipients()
returns integer
language sql
stable
as $$
  select least(2000, greatest(1, coalesce(
    (select (typed_value #>> '{}')::integer
     from public.app_settings where key = 'nearby_alert_max_recipients'),
    200)));
$$;

revoke execute on function app.review_reminder_after_hours()
  from public, anon, authenticated, service_role;
revoke execute on function app.nearby_alert_max_recipients()
  from public, anon, authenticated, service_role;

-- ===========================================================================
-- REVIEW_REMINDER
-- ===========================================================================
--
-- Sweep, not a trigger: "the booking completed N hours ago and you still have
-- not reviewed" is a statement about elapsed time, which no row change signals.
-- Runs from the same scheduler that runs `expire_stale_payment_pending` (0027).
--
-- Guarantees:
--   * At most ONE reminder per (booking, recipient), enforced by an existence
--     check against `notifications` — so re-running the sweep, or running two
--     instances concurrently, cannot spam a user. The advisory lock makes the
--     concurrent case deterministic rather than merely unlikely.
--   * Only while the review can still be submitted: once the blind window has
--     expired a reminder would be useless (and misleading).
--   * Never to a participant who has already reviewed, and never for a booking
--     where both reviews already exist.
-- ---------------------------------------------------------------------------
create or replace function public.emit_review_reminders(p_limit integer default 500)
returns integer
language plpgsql
security definer
set search_path = public, app
as $$
declare
  v_sent  integer := 0;
  v_limit integer := least(2000, greatest(1, coalesce(p_limit, 500)));
  v_row   record;
begin
  if not pg_try_advisory_xact_lock(hashtext('emit_review_reminders')) then
    return 0;
  end if;

  for v_row in
    select b.id            as booking_id,
           b.client_id,
           b.tasker_id,
           t.title         as task_title,
           done.completed_at
    from public.bookings b
    join public.tasks t on t.id = b.task_id
    join lateral (
      select max(be.created_at) as completed_at
      from public.booking_events be
      where be.booking_id = b.id and be.to_status = 'COMPLETED'
    ) done on true
    where b.status = 'COMPLETED'
      and done.completed_at is not null
      and done.completed_at
            <= now() - make_interval(hours => app.review_reminder_after_hours())
      -- Still inside the blind window: a reminder after expiry is pointless.
      and done.completed_at
            > now() - make_interval(days => app.review_reveal_days())
      and (select count(*) from public.reviews r where r.booking_id = b.id) < 2
    order by done.completed_at
    limit v_limit
  loop
    if not exists (select 1 from public.reviews r
                   where r.booking_id = v_row.booking_id
                     and r.reviewer_id = v_row.client_id)
       and not exists (select 1 from public.notifications n
                       where n.user_id = v_row.client_id
                         and n.type = 'REVIEW_REMINDER'
                         and n.resource_id = v_row.booking_id)
    then
      perform app.notify(
        v_row.client_id,
        'REVIEW_REMINDER',
        'Review your Tasker',
        format('Your review for "%s" is still private until both sides submit.', v_row.task_title),
        'booking',
        v_row.booking_id
      );
      v_sent := v_sent + 1;
    end if;

    if not exists (select 1 from public.reviews r
                   where r.booking_id = v_row.booking_id
                     and r.reviewer_id = v_row.tasker_id)
       and not exists (select 1 from public.notifications n
                       where n.user_id = v_row.tasker_id
                         and n.type = 'REVIEW_REMINDER'
                         and n.resource_id = v_row.booking_id)
    then
      perform app.notify(
        v_row.tasker_id,
        'REVIEW_REMINDER',
        'Review your Client',
        format('Your review for "%s" is still private until both sides submit.', v_row.task_title),
        'booking',
        v_row.booking_id
      );
      v_sent := v_sent + 1;
    end if;
  end loop;

  return v_sent;
end;
$$;

-- Service-role/scheduler only. An authenticated user has no reason to trigger a
-- fan-out, and letting them would turn a reminder into a spam primitive.
revoke execute on function public.emit_review_reminders(integer)
  from public, anon, authenticated;
grant execute on function public.emit_review_reminders(integer) to service_role;

-- ===========================================================================
-- NEARBY_TASK
-- ===========================================================================
--
-- Fires when a task becomes OPEN (publication), which is exactly the moment the
-- work becomes available to Taskers.
--
-- Recipient rule — deliberately conservative, because an alert is a push to a
-- stranger's phone:
--   * approved, non-suspended Tasker with an active account;
--   * never the task owner;
--   * declared a service area matching the task's PUBLIC locality — the city, and
--     the barangay when the Tasker named one. Locality matching, not a radius
--     query on the private point: the alert must never imply the exact address,
--     and `task_public_locations` is the approximate surface built for this.
--   * bounded fan-out (`nearby_alert_max_recipients`), so a single publication
--     cannot generate an unbounded write/push storm;
--   * one row per (task, recipient), and the user's `nearby` preference decides
--     delivery inside `app.notify` — the toggle from 0031 now governs something.
--
-- The task title is the only task detail included. No budget, no landmark, no
-- schedule: the notification is a pointer to a public task page, not a payload.
-- ---------------------------------------------------------------------------
create or replace function app.tg_notify_nearby_task()
returns trigger
language plpgsql
security definer
set search_path = public, app
as $$
declare
  v_loc public.task_public_locations;
  v_row record;
begin
  if new.status <> 'OPEN' then return new; end if;
  if tg_op = 'UPDATE' and old.status = 'OPEN' then return new; end if;

  select * into v_loc from public.task_public_locations where task_id = new.id;
  if not found then return new; end if;

  for v_row in
    select distinct sa.user_id
    from public.service_areas sa
    join public.tasker_profiles tp on tp.user_id = sa.user_id
    join public.profiles p on p.id = sa.user_id
    where sa.city_code = v_loc.city_code
      and (sa.barangay_code is null or sa.barangay_code = v_loc.barangay_code)
      and tp.approved_at is not null
      and tp.suspended_at is null
      and p.account_status = 'active'
      and sa.user_id <> new.client_id
    order by sa.user_id
    limit app.nearby_alert_max_recipients()
  loop
    if not exists (select 1 from public.notifications n
                   where n.user_id = v_row.user_id
                     and n.type = 'NEARBY_TASK'
                     and n.resource_id = new.id)
    then
      perform app.notify(
        v_row.user_id,
        'NEARBY_TASK',
        'New task in your area',
        format('"%s" was just posted in an area you serve.', new.title),
        'task',
        new.id
      );
    end if;
  end loop;

  return new;
end;
$$;

drop trigger if exists trg_notify_nearby_task_insert on public.tasks;
create trigger trg_notify_nearby_task_insert
  after insert on public.tasks
  for each row execute function app.tg_notify_nearby_task();

drop trigger if exists trg_notify_nearby_task_update on public.tasks;
create trigger trg_notify_nearby_task_update
  after update of status on public.tasks
  for each row execute function app.tg_notify_nearby_task();


-- ===================================================================
-- 0044_completion_timeout_and_push_retry.sql
-- ===================================================================

-- 0044_completion_timeout_and_push_retry.sql
-- Two Phase 3 exit-gate cases that had no implementation: the completion
-- TIMEOUT path, and safe notification RETRY.
--
-- ===========================================================================
-- 1. Completion timeout — WITHOUT inventing a money policy
-- ===========================================================================
--
-- The exit gate says "completion and hidden-review state machines pass happy,
-- retry, timeout, and unauthorised cases". The timeout case was missing: a Tasker
-- could request completion and, if the Client simply never returned to the app,
-- the booking sat in COMPLETION_REQUESTED forever with the funds protected and
-- nobody informed.
--
-- What this migration deliberately does NOT do: auto-confirm, auto-release, or
-- otherwise move money. Automatic release is an unapproved commercial/legal
-- policy (decision D13 / blocker 11.5). Implementing it here would fabricate a
-- funds-flow rule the parties have not agreed, which is exactly the failure mode
-- the delivery plan forbids ("never hide scope behind a mock", "no invented
-- penalty, fee, or refund").
--
-- What it does instead — the honest, reversible half of the timeout case:
--   * reminds the Client while the decision is still theirs;
--   * after a longer window, ESCALATES: an immutable `booking_events` row, an
--     audit entry, and a notification to both participants telling them the
--     booking needs attention/support. The booking status does not change, so no
--     protected money moves and the Admin/dispute path stays authoritative.
--
-- Exactly-once escalation is enforced by the existing
-- `uq_booking_event_idempotency (booking_id, idempotency_key)` constraint rather
-- than by hoping the scheduler runs once.

insert into public.app_settings (key, typed_value)
values ('completion_reminder_hours', '48'::jsonb),
       ('completion_escalation_hours', '168'::jsonb),
       ('push_max_attempts', '3'::jsonb)
on conflict (key) do nothing;

create or replace function app.completion_reminder_hours()
returns integer
language sql
stable
as $$
  select greatest(1, coalesce(
    (select (typed_value #>> '{}')::integer
     from public.app_settings where key = 'completion_reminder_hours'),
    48));
$$;

create or replace function app.completion_escalation_hours()
returns integer
language sql
stable
as $$
  select greatest(2, coalesce(
    (select (typed_value #>> '{}')::integer
     from public.app_settings where key = 'completion_escalation_hours'),
    168));
$$;

create or replace function app.push_max_attempts()
returns integer
language sql
stable
as $$
  select least(10, greatest(1, coalesce(
    (select (typed_value #>> '{}')::integer
     from public.app_settings where key = 'push_max_attempts'),
    3)));
$$;

revoke execute on function app.completion_reminder_hours()
  from public, anon, authenticated, service_role;
revoke execute on function app.completion_escalation_hours()
  from public, anon, authenticated, service_role;
revoke execute on function app.push_max_attempts()
  from public, anon, authenticated, service_role;

-- ---------------------------------------------------------------------------
-- sweep_stale_completion_requests (SERVER ONLY)
--
-- Returns the number of bookings acted on. Idempotent in both halves: the
-- reminder is deduplicated per (booking, recipient) against `notifications`, and
-- the escalation against the unique booking-event idempotency key.
-- ---------------------------------------------------------------------------
create or replace function public.sweep_stale_completion_requests(p_limit integer default 500)
returns integer
language plpgsql
security definer
set search_path = public, app
as $$
declare
  v_acted integer := 0;
  v_limit integer := least(2000, greatest(1, coalesce(p_limit, 500)));
  v_row   record;
  v_escalated boolean;
begin
  if not pg_try_advisory_xact_lock(hashtext('sweep_stale_completion_requests')) then
    return 0;
  end if;

  for v_row in
    select b.id as booking_id,
           b.client_id,
           b.tasker_id,
           t.title as task_title,
           req.requested_at
    from public.bookings b
    join public.tasks t on t.id = b.task_id
    join lateral (
      select max(be.created_at) as requested_at
      from public.booking_events be
      where be.booking_id = b.id and be.to_status = 'COMPLETION_REQUESTED'
    ) req on true
    where b.status = 'COMPLETION_REQUESTED'
      and req.requested_at is not null
      and req.requested_at
            <= now() - make_interval(hours => app.completion_reminder_hours())
    order by req.requested_at
    limit v_limit
  loop
    v_escalated := v_row.requested_at
      <= now() - make_interval(hours => app.completion_escalation_hours());

    if v_escalated then
      -- Immutable, exactly-once record that this booking timed out. The unique
      -- (booking_id, idempotency_key) constraint is the guarantee; the insert is
      -- allowed to lose the race and do nothing.
      insert into public.booking_events
        (booking_id, from_status, to_status, actor_id, source, idempotency_key, metadata)
      values
        (v_row.booking_id, 'COMPLETION_REQUESTED', 'COMPLETION_REQUESTED', null, 'system',
         'completion-timeout:' || v_row.booking_id::text,
         jsonb_build_object(
           'reason', 'completion_confirmation_timeout',
           'requested_at', v_row.requested_at,
           'escalation_hours', app.completion_escalation_hours(),
           -- Stated in the record itself so nobody later reads this event as an
           -- automatic release having happened.
           'funds_moved', false,
           'auto_release_policy', 'not_approved'))
      on conflict (booking_id, idempotency_key) do nothing;

      if not found then
        -- Already escalated on an earlier sweep: nothing more to do or say.
        continue;
      end if;

      insert into public.audit_logs (actor_id, action, resource_type, resource_id, safe_metadata)
      values (null, 'booking.completion.timeout', 'booking', v_row.booking_id,
              jsonb_build_object('requested_at', v_row.requested_at, 'funds_moved', false));

      perform app.notify(
        v_row.client_id,
        'COMPLETION_REMINDER',
        'Action needed on your booking',
        format('"%s" has been waiting for your confirmation. Confirm the work, or open a dispute if something is wrong.',
               v_row.task_title),
        'booking',
        v_row.booking_id);

      perform app.notify(
        v_row.tasker_id,
        'COMPLETION_REMINDER',
        'Your completion request is still waiting',
        format('"%s" has not been confirmed yet. Support can help if the Client does not respond.',
               v_row.task_title),
        'booking',
        v_row.booking_id);

      v_acted := v_acted + 1;
    else
      -- First reminder: the Client still owns the decision, so only they hear.
      if not exists (select 1 from public.notifications n
                     where n.user_id = v_row.client_id
                       and n.type = 'COMPLETION_REMINDER'
                       and n.resource_id = v_row.booking_id)
      then
        perform app.notify(
          v_row.client_id,
          'COMPLETION_REMINDER',
          'Confirm completed work',
          format('%s marked "%s" as finished. Confirm to release the protected payment.',
                 'Your Tasker', v_row.task_title),
          'booking',
          v_row.booking_id);
        v_acted := v_acted + 1;
      end if;
    end if;
  end loop;

  return v_acted;
end;
$$;

revoke execute on function public.sweep_stale_completion_requests(integer)
  from public, anon, authenticated;
grant execute on function public.sweep_stale_completion_requests(integer) to service_role;

-- ===========================================================================
-- 2. Safe push retry
-- ===========================================================================
--
-- `push-dispatch` wrote `delivery_status = 'FAILED'` and stopped. A transient
-- failure (Expo 5xx, a dropped connection, a cold start timing out) therefore
-- lost the push permanently, even though the in-app row survived.
--
-- Retry is bounded and recorded, not open-ended:
--   * `delivery_attempts` counts real send attempts;
--   * `next_attempt_at` is exponential backoff (2, 4, 8, ... minutes, capped at
--     an hour) so a provider outage is not hammered;
--   * once `delivery_attempts >= push_max_attempts` the row becomes terminal
--     (`next_attempt_at = null`) and is never picked up again — a failed push is
--     allowed to stay failed. The in-app notification is the durable channel;
--     push is best-effort by design.
--   * `delivery_error` stores a short, provider-supplied reason only. Bounded by
--     CHECK so an error blob cannot become a log-sized column, and never a token
--     or credential.
-- ---------------------------------------------------------------------------
alter table public.notifications
  add column if not exists delivery_attempts integer not null default 0,
  add column if not exists next_attempt_at   timestamptz,
  add column if not exists delivery_error    text;

alter table public.notifications
  drop constraint if exists chk_notification_delivery_error;
alter table public.notifications
  add constraint chk_notification_delivery_error
  check (delivery_error is null or char_length(delivery_error) <= 300);

alter table public.notifications
  drop constraint if exists chk_notification_delivery_attempts;
alter table public.notifications
  add constraint chk_notification_delivery_attempts
  check (delivery_attempts >= 0 and delivery_attempts <= 20);

-- Partial index: the retry sweep only ever looks at due failures.
create index if not exists ix_notifications_push_retry
  on public.notifications (next_attempt_at)
  where delivery_status = 'FAILED' and next_attempt_at is not null;

-- ---------------------------------------------------------------------------
-- record_push_delivery (SERVER ONLY) — the only writer of delivery bookkeeping.
--
-- Keeping the backoff/terminal decision in the database (rather than in the edge
-- function) means a second dispatcher, a manual replay, or a future provider
-- cannot disagree about when a notification may be retried.
-- ---------------------------------------------------------------------------
create or replace function public.record_push_delivery(
  p_notification_id uuid,
  p_outcome text,
  p_error text default null
)
returns public.notifications
language plpgsql
security definer
set search_path = public, app
as $$
declare
  v_row public.notifications;
  v_attempts integer;
  v_max integer := app.push_max_attempts();
  v_backoff_minutes integer;
begin
  if p_outcome not in ('SENT', 'FAILED', 'SUPPRESSED') then
    raise exception 'VALIDATION_ERROR: unsupported push outcome %', p_outcome
      using errcode = 'check_violation';
  end if;

  select * into v_row from public.notifications where id = p_notification_id for update;
  if not found then
    raise exception 'NOT_FOUND: notification %', p_notification_id using errcode = 'no_data_found';
  end if;

  if p_outcome = 'FAILED' then
    v_attempts := v_row.delivery_attempts + 1;
    -- 2, 4, 8, 16, 32, 60, 60 ... minutes.
    v_backoff_minutes := least(60, power(2, least(v_attempts, 6))::integer);
    update public.notifications
       set delivery_status   = 'FAILED',
           delivery_attempts = v_attempts,
           delivery_error    = left(coalesce(p_error, 'unspecified provider failure'), 300),
           next_attempt_at   = case
             when v_attempts >= v_max then null
             else now() + make_interval(mins => v_backoff_minutes)
           end
     where id = p_notification_id
    returning * into v_row;
  else
    update public.notifications
       set delivery_status   = p_outcome::notification_delivery_status,
           delivery_attempts = v_row.delivery_attempts
             + case when p_outcome = 'SENT' then 1 else 0 end,
           delivery_error    = null,
           next_attempt_at   = null
     where id = p_notification_id
    returning * into v_row;
  end if;

  return v_row;
end;
$$;

revoke execute on function public.record_push_delivery(uuid, text, text)
  from public, anon, authenticated;
grant execute on function public.record_push_delivery(uuid, text, text) to service_role;

-- ---------------------------------------------------------------------------
-- due_push_retries (SERVER ONLY) — what the dispatcher should try again.
--
-- Read-only: claiming/marking happens through `record_push_delivery` once the
-- attempt has actually been made, so a dispatcher that dies mid-run leaves the
-- row retryable rather than silently consumed.
-- ---------------------------------------------------------------------------
create or replace function public.due_push_retries(p_limit integer default 100)
returns table (
  id uuid,
  user_id uuid,
  type text,
  title text,
  body text,
  resource_type text,
  resource_id uuid,
  delivery_attempts integer
)
language sql
security definer
set search_path = public, app
as $$
  select n.id, n.user_id, n.type, n.title, n.body,
         n.resource_type, n.resource_id, n.delivery_attempts
  from public.notifications n
  where n.delivery_status = 'FAILED'
    and n.next_attempt_at is not null
    and n.next_attempt_at <= now()
    and n.delivery_attempts < app.push_max_attempts()
  order by n.next_attempt_at
  limit least(500, greatest(1, coalesce(p_limit, 100)));
$$;

revoke execute on function public.due_push_retries(integer)
  from public, anon, authenticated;
grant execute on function public.due_push_retries(integer) to service_role;


-- ===================================================================
-- 0045_scheduled_jobs.sql
-- ===================================================================

-- 0045_scheduled_jobs.sql
-- Actually RUN the recurring server jobs.
--
-- Four server-only sweeps existed with no caller:
--
--   * `expire_stale_payment_pending` (0027) — abandoned checkouts stayed
--     PAYMENT_PENDING forever, holding the one-active-booking slot on a task.
--   * `emit_review_reminders` (0043) — the blind review window could expire in
--     silence.
--   * `sweep_stale_completion_requests` (0044) — a completion request the Client
--     never answered was never reminded or escalated.
--   * the push retry queue (`due_push_retries`, 0044) — a transiently failed push
--     was never attempted again.
--
-- Each was written, tested, and then invoked by nothing: no `pg_cron` schedule, no
-- scheduled workflow, no runbook. A sweep that never runs is indistinguishable
-- from an unimplemented one, so this migration wires them up.
--
-- DESIGN
--
-- 1. **Extensions are not created here.** `pg_cron` needs
--    `shared_preload_libraries` and, on hosted Supabase, is enabled from the
--    Dashboard. A migration that assumed it would fail on any database without
--    it — including CI and disposable test containers. Instead, scheduling is
--    guarded: present → schedule; absent → NOTICE and skip, leaving the migration
--    successful and the jobs runnable manually.
-- 2. **Idempotent.** `app.ensure_scheduled_jobs()` can be re-run after enabling
--    `pg_cron` (or after changing a cadence) and converges on the same schedule.
--    It is also the documented ops step in
--    `docs/operations/scheduled-jobs.md`.
-- 3. **No secret in a job command.** The push retry needs an HTTPS call, so the
--    cron entry invokes `app.dispatch_push_retries()`, which reads the URL and
--    dispatch secret from Supabase Vault at run time. Nothing is embedded in
--    `cron.job.command`, and a missing secret is a no-op, never a fabricated call.
-- 4. **Dynamic SQL for optional schemas.** `cron.*`, `net.*`, and `vault.*` are
--    referenced through `execute` so these functions can be created on a database
--    where those schemas do not exist yet.
--
-- Cadence rationale: checkout expiry is the only one a user waits on, so it runs
-- most often; reminders and escalation are day-scale rules, so hourly is ample
-- and keeps the notification volume honest. Offsets stagger the jobs so they
-- never start in the same second.

-- ---------------------------------------------------------------------------
-- app.dispatch_push_retries — ask the push-dispatch function to retry due rows.
--
-- Returns true only when a request was actually sent. The three "not configured"
-- paths (no pg_net, no Vault, no secret) are silent no-ops by design: this runs on
-- a schedule, and a database where push has not been provisioned must not fill
-- the log with failures for a channel the Client has not enabled yet (B4).
-- ---------------------------------------------------------------------------
create or replace function app.dispatch_push_retries(p_limit integer default 100)
returns boolean
language plpgsql
security definer
set search_path = public, app
as $$
declare
  v_url    text;
  v_secret text;
  v_limit  integer := least(500, greatest(1, coalesce(p_limit, 100)));
begin
  if not exists (select 1 from pg_extension where extname = 'pg_net') then
    raise notice 'push retry skipped: pg_net is not installed';
    return false;
  end if;
  if to_regclass('vault.decrypted_secrets') is null then
    raise notice 'push retry skipped: Supabase Vault is not available';
    return false;
  end if;

  execute $q$
    select max(case when name = 'push_dispatch_url' then decrypted_secret end),
           max(case when name = 'push_dispatch_secret' then decrypted_secret end)
    from vault.decrypted_secrets
    where name in ('push_dispatch_url', 'push_dispatch_secret')
  $q$ into v_url, v_secret;

  if v_url is null or v_secret is null then
    raise notice 'push retry skipped: push_dispatch_url/push_dispatch_secret not set in Vault';
    return false;
  end if;

  execute format(
    'select net.http_post(url := %L, headers := %L::jsonb, body := %L::jsonb)',
    v_url,
    jsonb_build_object('content-type', 'application/json', 'x-dispatch-secret', v_secret),
    jsonb_build_object('mode', 'retry', 'limit', v_limit)
  );
  return true;
end;
$$;

revoke execute on function app.dispatch_push_retries(integer)
  from public, anon, authenticated, service_role;

-- ---------------------------------------------------------------------------
-- app.ensure_scheduled_jobs — declare the schedule.
--
-- Returns a jsonb report of what was scheduled or skipped, so an operator (and
-- the runbook) can see the outcome rather than guessing.
-- ---------------------------------------------------------------------------
create or replace function app.ensure_scheduled_jobs()
returns jsonb
language plpgsql
security definer
set search_path = public, app
as $$
declare
  v_jobs   jsonb := '[]'::jsonb;
  v_job    record;
  v_has_cron boolean;
begin
  select exists (select 1 from pg_extension where extname = 'pg_cron') into v_has_cron;
  if not v_has_cron then
    raise notice 'pg_cron is not installed: no jobs scheduled. Enable it, then run select app.ensure_scheduled_jobs();';
    return jsonb_build_object('scheduled', false, 'reason', 'pg_cron_not_installed');
  end if;

  for v_job in
    select *
    from (values
      -- name, cron schedule, command
      ('dizkarte-expire-stale-checkouts', '*/15 * * * *',
       'select public.expire_stale_payment_pending(60);'),
      ('dizkarte-review-reminders', '15 * * * *',
       'select public.emit_review_reminders(500);'),
      ('dizkarte-completion-sweep', '35 * * * *',
       'select public.sweep_stale_completion_requests(500);'),
      ('dizkarte-push-retry', '*/10 * * * *',
       'select app.dispatch_push_retries(100);')
    ) as j(name, schedule, command)
  loop
    -- Unschedule first so a changed cadence replaces the old entry instead of
    -- depending on pg_cron's upsert-by-name behaviour across versions.
    begin
      execute format('select cron.unschedule(%L)', v_job.name);
    exception when others then
      null; -- not scheduled yet
    end;

    execute format('select cron.schedule(%L, %L, %L)', v_job.name, v_job.schedule, v_job.command);

    v_jobs := v_jobs || jsonb_build_object(
      'name', v_job.name, 'schedule', v_job.schedule, 'command', v_job.command);
  end loop;

  return jsonb_build_object('scheduled', true, 'jobs', v_jobs);
end;
$$;

revoke execute on function app.ensure_scheduled_jobs()
  from public, anon, authenticated, service_role;

-- ---------------------------------------------------------------------------
-- Apply the schedule now (no-op without pg_cron).
-- ---------------------------------------------------------------------------
do $$
declare v_result jsonb;
begin
  v_result := app.ensure_scheduled_jobs();
  raise notice 'scheduled jobs: %', v_result;
end $$;


-- ===================================================================
-- 0046_conversation_read_state.sql
-- ===================================================================

-- 0046_conversation_read_state.sql
-- Per-conversation read state, and a bounded summary read model for the
-- Bookings list.
--
-- WHY
--
-- Unread was only ever modelled per NOTIFICATION (`notifications.read_at` on a
-- `MESSAGE_RECEIVED` row). That answers "have you looked at your inbox?", not
-- "does this conversation have messages you have not read?" — so the Bookings
-- list could not show a per-conversation badge or a last-message preview without
-- fetching every message of every booking to the client and computing it there.
--
-- WHAT
--
--   1. `conversation_participants.last_read_at` — the participant's own high-water
--      mark. Monotonic: `mark_conversation_read` never moves it backwards, so an
--      out-of-order call (a stale screen, a retried request) cannot resurrect
--      messages the user has already seen.
--   2. `conversation_summaries()` — one bounded row per conversation the CALLER
--      participates in: last message time, a short preview, who sent it, and the
--      caller's unread count.
--
-- PRIVACY
--
-- The summary is `SECURITY DEFINER` but hard-scoped to `auth.uid()`: it never
-- takes a user id argument, so there is no parameter to tamper with. It reads
-- only conversations the caller participates in, which by construction exist
-- only for a payment-confirmed booking (`process_payment_event` is the sole
-- creator), so this adds no new pre-payment surface.
--
-- Two deliberate exclusions:
--   * only `moderation_status = 'APPROVED'` messages are previewed or counted —
--     a message an Admin removed must not reappear as preview text;
--   * the preview is truncated in SQL (140 chars), so a 4,000-character message
--     cannot turn a list query into a bulk content transfer. The full body is
--     still only readable inside the conversation itself.

alter table public.conversation_participants
  add column if not exists last_read_at timestamptz;

-- The unread count and the summary both filter by participant + time.
create index if not exists ix_messages_conversation_created
  on public.messages (conversation_id, created_at desc);

-- ---------------------------------------------------------------------------
-- mark_conversation_read — participant-only, monotonic, idempotent.
--
-- Returns the effective high-water mark, so a caller can tell what was recorded
-- without a second read.
-- ---------------------------------------------------------------------------
create or replace function public.mark_conversation_read(p_conversation_id uuid)
returns timestamptz
language plpgsql
security definer
set search_path = public, app
as $$
declare
  v_now timestamptz := now();
  v_result timestamptz;
begin
  if auth.uid() is null then
    raise exception 'FORBIDDEN: authentication is required.'
      using errcode = 'insufficient_privilege';
  end if;

  update public.conversation_participants cp
     set last_read_at = greatest(coalesce(cp.last_read_at, v_now), v_now)
   where cp.conversation_id = p_conversation_id
     and cp.user_id = auth.uid()
  returning cp.last_read_at into v_result;

  if not found then
    -- Not a participant (or no such conversation): the same refusal either way,
    -- so this cannot be used to probe which bookings exist.
    raise exception 'FORBIDDEN: only conversation participants may mark it read.'
      using errcode = 'insufficient_privilege';
  end if;

  return v_result;
end;
$$;

-- ---------------------------------------------------------------------------
-- conversation_summaries — the Bookings-list read model.
--
-- One row per conversation the caller participates in, ordered by most recent
-- activity. `unread_count` counts APPROVED messages from the OTHER participant
-- newer than the caller's high-water mark; a participant's own messages are
-- never unread to themselves, and a never-opened conversation counts everything
-- from the counterpart.
-- ---------------------------------------------------------------------------
create or replace function public.conversation_summaries()
returns table (
  conversation_id uuid,
  booking_id uuid,
  last_message_at timestamptz,
  last_message_preview text,
  last_message_sender_id uuid,
  last_message_has_media boolean,
  unread_count integer
)
language sql
security definer
set search_path = public, app
as $$
  with mine as (
    select cp.conversation_id, cp.last_read_at
    from public.conversation_participants cp
    where cp.user_id = auth.uid()
  ),
  latest as (
    select distinct on (m.conversation_id)
           m.conversation_id,
           m.created_at,
           m.body,
           m.sender_id,
           m.id as message_id
    from public.messages m
    join mine on mine.conversation_id = m.conversation_id
    where m.moderation_status = 'APPROVED'
    order by m.conversation_id, m.created_at desc
  )
  select c.id as conversation_id,
         c.booking_id,
         latest.created_at as last_message_at,
         left(latest.body, 140) as last_message_preview,
         latest.sender_id as last_message_sender_id,
         exists (
           select 1 from public.message_media mm where mm.message_id = latest.message_id
         ) as last_message_has_media,
         (
           select count(*)::integer
           from public.messages m2
           where m2.conversation_id = c.id
             and m2.moderation_status = 'APPROVED'
             and m2.sender_id <> auth.uid()
             and (mine.last_read_at is null or m2.created_at > mine.last_read_at)
         ) as unread_count
  from public.conversations c
  join mine on mine.conversation_id = c.id
  left join latest on latest.conversation_id = c.id
  order by latest.created_at desc nulls last;
$$;

-- Explicit ACLs. A bare `create function` grants EXECUTE to PUBLIC, which `anon`
-- inherits — revoking from `anon` alone would not remove it. Revoke from PUBLIC
-- first, then re-grant only the intended role, matching the 0013 convention.
--
-- `service_role` is deliberately excluded: both functions resolve the caller
-- through `auth.uid()`, so a service-role call carries no identity and would
-- silently return nothing. A server-side path that needs this data should read
-- the underlying tables directly, where the intent is explicit.
revoke execute on function public.conversation_summaries()
  from public, anon, authenticated, service_role;
grant execute on function public.conversation_summaries() to authenticated;

revoke execute on function public.mark_conversation_read(uuid)
  from public, anon, authenticated, service_role;
grant execute on function public.mark_conversation_read(uuid) to authenticated;


-- ===================================================================
-- 0047_task_feed_no_offers_filter.sql
-- ===================================================================

-- 0047_task_feed_no_offers_filter.sql
-- "Show tasks with no offers" - the one browse filter the marketplace reference
-- has that this feed did not - plus the defect that filter uncovered.
--
-- DEFECT FOUND WHILE TESTING: `offer_count` was per-viewer, not per-task.
--
-- `public_task_feed` is `security_invoker = true`, and its `offer_count` was an
-- inline `select count(*) from offers ...`. Offer rows are private per viewer (the
-- task owner sees all, a Tasker sees only their own, anyone else sees none), so
-- that subquery was evaluated under the READER's RLS:
--
--   * the task owner saw the true count;
--   * a Tasker browsing saw 1 for their own quote and **0 for every other task**;
--   * a signed-out/unrelated viewer saw 0 everywhere.
--
-- So the number on a browse card was already wrong for the audience that reads it
-- most, and a "no offers yet" filter built on it would have matched everything.
--
-- Fix: the COUNT is computed by a `SECURITY DEFINER` helper, so it reflects the
-- task rather than the reader. This is an aggregate-only disclosure and is
-- deliberately narrow - `app.task_submitted_offer_count` returns a number and
-- nothing else. Which Taskers quoted, at what price, and with what message all
-- stay governed by the existing per-viewer `offers` policies; nothing about offer
-- CONTENT visibility changes here.
--
-- WHY THE OLD SIGNATURE IS DROPPED FIRST
--
-- `search_task_feed` gains a parameter. Adding one to a `create or replace` would
-- leave the previous 15-argument function in place as a separate OVERLOAD, and
-- PostgREST resolves overloads by the argument names a caller supplies - so the
-- app could keep binding to the old one and the filter would silently do nothing.
-- Dropping the old signature explicitly guarantees exactly one
-- `search_task_feed` exists.
--
-- The function body below is 0024's, unchanged except for the new parameter and
-- its single predicate: the page-size clamp, half-origin degradation, radius cap,
-- `st_dwithin` index form, 100 m distance rounding, and sort/tiebreak order all
-- keep their existing behaviour.

-- ---------------------------------------------------------------------------
-- app.task_submitted_offer_count - a task fact, not a viewer fact.
-- ---------------------------------------------------------------------------
create or replace function app.task_submitted_offer_count(p_task_id uuid)
returns bigint
language sql
stable
security definer
set search_path = public, app
as $$
  select count(*)
  from public.offers o
  where o.task_id = p_task_id
    and o.status = 'SUBMITTED';
$$;

-- The public feed is readable by `anon` as well, so both API roles need EXECUTE.
-- Revoke from PUBLIC first: a bare `create function` grants EXECUTE to PUBLIC.
revoke execute on function app.task_submitted_offer_count(uuid)
  from public, anon, authenticated, service_role;
grant execute on function app.task_submitted_offer_count(uuid) to authenticated, anon, service_role;

-- ---------------------------------------------------------------------------
-- public_task_feed - recreated verbatim from 0008 with the count delegated.
--
-- Same column names and types (so `create or replace view` is legal), and
-- `security_invoker` is re-asserted: every other column must keep being read
-- under the caller's own RLS. Only the count is elevated.
-- ---------------------------------------------------------------------------
create or replace view public.public_task_feed as
select t.id,
       t.category_id,
       t.title,
       t.description,
       t.budget_centavos,
       t.currency,
       t.status,
       t.same_day,
       t.scheduled_for,
       t.published_at,
       pl.city_code,
       pl.barangay_code,
       pl.landmark,
       round(st_y(pl.approximate_point::geometry)::numeric, 3) as approximate_lat,
       round(st_x(pl.approximate_point::geometry)::numeric, 3) as approximate_lng,
       pl.approximate_point,
       app.task_submitted_offer_count(t.id) as offer_count
from public.tasks t
join public.task_public_locations pl on pl.task_id = t.id
where t.status = 'OPEN';

alter view public.public_task_feed set (security_invoker = true);

drop function if exists public.search_task_feed(
  text, uuid, text, text, bigint, bigint, timestamptz, timestamptz, boolean,
  double precision, double precision, double precision, text, integer, integer
);
create or replace function public.search_task_feed(
  p_keyword        text default null,
  p_category_id    uuid default null,
  p_city_code      text default null,
  p_barangay_code  text default null,
  p_min_budget     bigint default null,
  p_max_budget     bigint default null,
  p_scheduled_from timestamptz default null,
  p_scheduled_to   timestamptz default null,
  p_same_day_only  boolean default false,
  p_near_lat       double precision default null,
  p_near_lng       double precision default null,
  p_radius_km      double precision default null,
  p_sort           text default 'newest',
  p_page           integer default 1,
  p_page_size      integer default 20,
  -- New: restrict to tasks that have attracted no offer yet.
  p_no_offers_only boolean default false
)
returns table (
  id               uuid,
  category_id      uuid,
  title            text,
  description      text,
  budget_centavos  bigint,
  currency         text,
  status           task_status,
  same_day         boolean,
  scheduled_for    timestamptz,
  published_at     timestamptz,
  city_code        text,
  barangay_code    text,
  landmark         text,
  approximate_lat  numeric,
  approximate_lng  numeric,
  offer_count      bigint,
  distance_m       double precision,
  total_count      bigint
)
language sql
stable
security invoker
set search_path = public
as $$
with bounds as (
  select
    -- Page size is clamped server-side so a client cannot ask for the whole table.
    least(greatest(coalesce(p_page_size, 20), 1), 100) as page_size,
    greatest(coalesce(p_page, 1), 1)                   as page,
    -- A coordinate pair is only usable if both halves are present and in range;
    -- a half-supplied origin silently degrades to a non-geographic search
    -- rather than matching everything or nothing.
    case
      when p_near_lat is null or p_near_lng is null then null
      when p_near_lat < -90 or p_near_lat > 90 then null
      when p_near_lng < -180 or p_near_lng > 180 then null
      else st_setsrid(st_makepoint(p_near_lng, p_near_lat), 4326)::geography
    end as origin,
    -- Unbounded radius searches scan the country; 100 km covers any realistic
    -- travel distance for a task in a Philippine city.
    case
      when p_radius_km is null or p_radius_km <= 0 then null
      else least(p_radius_km, 100) * 1000
    end as radius_m
),
matched as (
  select
    f.*,
    -- st_distance on geography returns metres.
    case when b.origin is null then null
         else round(st_distance(f.approximate_point, b.origin) / 100.0) * 100
    end as distance_m,
    b.page_size,
    b.page,
    b.origin
  from public.public_task_feed f
  cross join bounds b
  where (p_keyword is null
         or f.title ilike '%' || p_keyword || '%'
         or f.description ilike '%' || p_keyword || '%')
    and (p_category_id is null or f.category_id = p_category_id)
    and (p_city_code is null or f.city_code = p_city_code)
    and (p_barangay_code is null or f.barangay_code = p_barangay_code)
    and (p_min_budget is null or f.budget_centavos >= p_min_budget)
    and (p_max_budget is null or f.budget_centavos <= p_max_budget)
    and (p_scheduled_from is null or f.scheduled_for >= p_scheduled_from)
    and (p_scheduled_to is null or f.scheduled_for <= p_scheduled_to)
    and (p_same_day_only is not true or f.same_day = true)
    -- Unquoted work only. `is not true` keeps a null flag equivalent to "off",
    -- matching how every other boolean filter here behaves.
    and (p_no_offers_only is not true or coalesce(f.offer_count, 0) = 0)
    -- st_dwithin is the index-using form; a radius without an origin is ignored
    -- rather than treated as "0 km", which would return nothing.
    and (b.origin is null or b.radius_m is null
         or st_dwithin(f.approximate_point, b.origin, b.radius_m))
)
select
  m.id,
  m.category_id,
  m.title,
  m.description,
  m.budget_centavos,
  m.currency,
  m.status,
  m.same_day,
  m.scheduled_for,
  m.published_at,
  m.city_code,
  m.barangay_code,
  m.landmark,
  m.approximate_lat,
  m.approximate_lng,
  m.offer_count,
  m.distance_m,
  count(*) over () as total_count
from matched m
order by
  -- 'nearby' without a usable origin falls back to recency instead of
  -- inventing an order the caller would read as distance.
  case when p_sort = 'nearby' and m.origin is not null then m.distance_m end asc nulls last,
  case when p_sort = 'highest_budget' then m.budget_centavos end desc nulls last,
  m.published_at desc nulls last,
  m.id
limit  (select page_size from bounds)
offset ((select page from bounds) - 1) * (select page_size from bounds);
$$;

grant execute on function public.search_task_feed(
  text, uuid, text, text, bigint, bigint, timestamptz, timestamptz, boolean,
  double precision, double precision, double precision, text, integer, integer, boolean
) to authenticated, anon;


-- ===================================================================
-- 0048_report_submission.sql
-- ===================================================================

-- 0048_report_submission.sql
-- Give `reports` a producer.
--
-- THE GAP
--
-- The table has existed since 0007 (with `resource_type` already allowing
-- `message`), the Admin queue consumes it, and 0013 built assignment-scoped,
-- audited narrative/evidence reads for it. But **nothing in the product ever
-- created a report**: the only writer in the repository was a seed script, and the
-- mobile app offers support TICKETS only. So the Admin reports queue could never
-- receive a real report — the same class of defect as the notification producers
-- fixed in 0043 (written, tested, called by nothing).
--
-- WHY AN RPC RATHER THAN THE EXISTING INSERT POLICY
--
-- `reports_insert` (0009) allowed an authenticated user to insert their own OPEN
-- report directly. That is not enough:
--
--   * it accepts ANY `resource_id`, including a message, booking, or offer the
--     reporter cannot see — so a stranger could file a report referencing private
--     rows, and an Admin would then open an audited case about content the
--     reporter had no legitimate view of;
--   * nothing bounds volume, so a client loop could flood the queue;
--   * the CHECK constraints raise raw constraint errors, not the app's
--     `VALIDATION_ERROR` contract.
--
-- So this migration adds `submit_report`, which re-checks authorization per
-- resource type, and **removes the direct INSERT policy** so the RPC is the only
-- writer. Same pattern as `notifications` (no INSERT policy; `app.notify` is the
-- only path).
--
-- WHAT IT DOES NOT DO
--
-- No blocking, no auto-moderation, no notification to the reported user. A report
-- opens an Admin case; it changes nothing about the reported resource. Blocking a
-- counterpart mid-booking has refund/completion consequences that decision D13 /
-- blocker 11.5 have not settled, so it stays out of scope.

-- ---------------------------------------------------------------------------
-- submit_report — one report per (reporter, resource) while a case is open.
--
-- Idempotent by construction: a second submission for a resource this reporter
-- has already reported returns the existing row rather than stacking duplicates
-- on the Admin queue. Re-reporting is possible once the earlier case is closed
-- (ACTIONED/DISMISSED), which is the legitimate "it happened again" path.
--
-- The visibility rule per resource type answers one question: could this reporter
-- legitimately have SEEN the thing they are reporting?
--
--   task     — publicly listed (OPEN), or the reporter owns it, or they are a
--              participant in its booking.
--   message  — the reporter participates in that conversation. Chat is gated
--              behind payment confirmation, so this also means the booking is
--              confirmed. Reporting your OWN message is refused as meaningless.
--   offer    — the task owner, or the Tasker who made it.
--   booking  — a participant.
--   user     — any active account may report another; never yourself.
-- ---------------------------------------------------------------------------
create or replace function public.submit_report(
  p_resource_type text,
  p_resource_id   uuid,
  p_category      text,
  p_narrative     text
)
returns public.reports
language plpgsql
security definer
set search_path = public, app
as $$
declare
  v_actor     uuid := auth.uid();
  v_report    public.reports;
  v_narrative text := btrim(coalesce(p_narrative, ''));
  v_allowed   boolean := false;
begin
  if v_actor is null then
    raise exception 'FORBIDDEN: authentication is required.'
      using errcode = 'insufficient_privilege';
  end if;
  if not exists (select 1 from public.profiles p
                 where p.id = v_actor and p.account_status = 'active') then
    raise exception 'FORBIDDEN: only an active account may report.'
      using errcode = 'insufficient_privilege';
  end if;

  if p_resource_type not in ('task', 'user', 'message', 'offer', 'booking') then
    raise exception 'VALIDATION_ERROR: unsupported report resource type %', p_resource_type
      using errcode = 'check_violation';
  end if;
  if p_category not in ('fraud', 'harassment', 'inappropriate', 'safety', 'spam', 'other') then
    raise exception 'VALIDATION_ERROR: unsupported report category %', p_category
      using errcode = 'check_violation';
  end if;
  -- Bounds checked here so the caller gets the app's error contract rather than a
  -- raw CHECK violation from the table.
  if char_length(v_narrative) < 10 or char_length(v_narrative) > 4000 then
    raise exception 'VALIDATION_ERROR: a report needs between 10 and 4000 characters.'
      using errcode = 'check_violation';
  end if;

  -- ---- Could this reporter legitimately see the resource? ----
  if p_resource_type = 'task' then
    select exists (
      select 1 from public.tasks t
      where t.id = p_resource_id
        and (t.status = 'OPEN'
             or t.client_id = v_actor
             or exists (select 1 from public.bookings b
                        where b.task_id = t.id
                          and (b.client_id = v_actor or b.tasker_id = v_actor)))
    ) into v_allowed;

  elsif p_resource_type = 'message' then
    select exists (
      select 1
      from public.messages m
      join public.conversation_participants cp on cp.conversation_id = m.conversation_id
      where m.id = p_resource_id
        and cp.user_id = v_actor
        -- Reporting your own message would open a case about yourself.
        and m.sender_id <> v_actor
    ) into v_allowed;

  elsif p_resource_type = 'offer' then
    select exists (
      select 1
      from public.offers o
      join public.tasks t on t.id = o.task_id
      where o.id = p_resource_id
        and (t.client_id = v_actor or o.tasker_id = v_actor)
    ) into v_allowed;

  elsif p_resource_type = 'booking' then
    select exists (
      select 1 from public.bookings b
      where b.id = p_resource_id
        and (b.client_id = v_actor or b.tasker_id = v_actor)
    ) into v_allowed;

  else -- 'user'
    select exists (
      select 1 from public.profiles p
      where p.id = p_resource_id and p.id <> v_actor
    ) into v_allowed;
  end if;

  if not v_allowed then
    -- Deliberately the same refusal whether the resource is invisible, absent, or
    -- the reporter themselves: the error must not become a probe for which
    -- messages, offers, or bookings exist.
    raise exception 'FORBIDDEN: you cannot report this resource.'
      using errcode = 'insufficient_privilege';
  end if;

  -- ---- One live case per (reporter, resource) ----
  select * into v_report
  from public.reports r
  where r.reporter_id = v_actor
    and r.resource_type = p_resource_type
    and r.resource_id = p_resource_id
    and r.status in ('OPEN', 'TRIAGED')
  order by r.created_at
  limit 1;
  if found then
    return v_report;
  end if;

  insert into public.reports (reporter_id, resource_type, resource_id, category, narrative)
  values (v_actor, p_resource_type, p_resource_id, p_category, v_narrative)
  returning * into v_report;

  return v_report;
end;
$$;

revoke execute on function public.submit_report(text, uuid, text, text)
  from public, anon, authenticated, service_role;
grant execute on function public.submit_report(text, uuid, text, text) to authenticated;

-- ---------------------------------------------------------------------------
-- The RPC is now the only writer.
--
-- Dropping the direct INSERT policy closes the path that bypassed every check
-- above. Reads are untouched: a reporter still sees their own reports, an
-- assignee sees theirs, and Admin capability reads stay exactly as 0009/0013 left
-- them. The service role (seeds, back-office jobs) bypasses RLS and is unaffected.
-- ---------------------------------------------------------------------------
drop policy if exists reports_insert on public.reports;

-- A reporter's own list, and the duplicate-suppression lookup above, both filter
-- on (reporter, resource).
create index if not exists ix_reports_reporter_resource
  on public.reports (reporter_id, resource_type, resource_id);


-- ===================================================================
-- 0049_admin_case_subject.sql
-- ===================================================================

-- 0049_admin_case_subject.sql
-- Resolve what an Admin case is actually ABOUT, from the live app data.
--
-- Before this migration the Admin console could name a case subject only as its
-- type plus eight hex characters of a UUID ("message 3f2a1b9c", "booking 7c14a2de").
-- A support Admin triaging a report could read the reporter's narrative but not the
-- reported message; a finance Admin opening a dispute saw neither the parties nor
-- the task. Acting on a case therefore meant querying the database by hand, which
-- is both slow and unaudited — the opposite of what the assignment-scoped read
-- functions in 0013 were built for.
--
-- This adds one internal resolver plus two audited, assignment-scoped entry points.
-- The resolver reads live rows, so the Admin console reflects the app's current
-- state rather than a snapshot taken when the case was filed.
--
-- Disclosure rules held here, deliberately:
--   * display names, statuses, amounts, and timestamps only;
--   * NO mobile number, NO email, NO exact location, NO storage paths;
--   * counts stay aggregate (how many reports, not who else reported);
--   * a message body IS included, because moderating content you cannot read is
--     not moderation — and the assigned Admin can already read the whole
--     transcript through `admin_read_conversation_messages` (0013), so this
--     discloses nothing new, just the one message the case is about.
--
-- Access is the same shape as every other sensitive Admin read: only the ASSIGNED
-- Admin, only with a reason + idempotency key, and audited exactly once per key.

-- ---------------------------------------------------------------------------
-- Internal resolver. Not granted to any client role.
-- ---------------------------------------------------------------------------
create or replace function app.case_subject_json(
  p_resource_type text,
  p_resource_id uuid
)
returns jsonb
language plpgsql
stable
security definer
set search_path = public, app
as $$
declare
  v_subject jsonb;
begin
  -- Every branch returns the same key set so the Admin console can render one
  -- component for all case types instead of five special cases.
  case p_resource_type
    when 'task' then
      select jsonb_build_object(
               'exists', true,
               'kind', 'task',
               'label', format('Task "%s" (%s)', t.title, t.status),
               'status', t.status::text,
               'body', left(t.description, 2000),
               'occurredAt', coalesce(t.published_at, t.created_at),
               'subjectUserId', t.client_id,
               'subjectUserName', p.display_name,
               'counterpartyName', null,
               'taskId', t.id,
               'taskTitle', t.title,
               'bookingId', (select b.id from public.bookings b
                              where b.task_id = t.id order by b.created_at desc limit 1),
               'amountCentavos', t.budget_centavos,
               'extra', jsonb_build_object('categoryName', c.name, 'offerCount',
                          (select count(*) from public.offers o
                            where o.task_id = t.id and o.status <> 'WITHDRAWN'))
             )
        into v_subject
        from public.tasks t
        join public.profiles p on p.id = t.client_id
        left join public.categories c on c.id = t.category_id
       where t.id = p_resource_id;

    when 'user' then
      select jsonb_build_object(
               'exists', true,
               'kind', 'user',
               'label', format('Profile "%s" (%s)', p.display_name, p.account_status),
               'status', p.account_status::text,
               'body', left(p.bio, 2000),
               'occurredAt', p.created_at,
               'subjectUserId', p.id,
               'subjectUserName', p.display_name,
               'counterpartyName', null,
               'taskId', null,
               'taskTitle', null,
               'bookingId', null,
               'amountCentavos', null,
               -- Aggregate reputation only: the same disclosure the public
               -- profile already makes, never individual review rows.
               'extra', jsonb_build_object(
                 'isTasker', tp.user_id is not null,
                 'taskerApproved', tp.approved_at is not null,
                 'taskerSuspended', tp.suspended_at is not null,
                 'completionCount', coalesce(tp.completion_count, 0),
                 'ratingCount', coalesce(tp.rating_count, 0),
                 'ratingAverage', case when coalesce(tp.rating_count, 0) = 0 then null
                                       else round(tp.rating_sum::numeric / tp.rating_count, 2) end,
                 'tasksPosted', (select count(*) from public.tasks t where t.client_id = p.id))
             )
        into v_subject
        from public.profiles p
        left join public.tasker_profiles tp on tp.user_id = p.id
       where p.id = p_resource_id;

    when 'message' then
      select jsonb_build_object(
               'exists', true,
               'kind', 'message',
               'label', format('Message from "%s" in booking %s',
                               sender.display_name, left(bk.id::text, 8)),
               'status', m.moderation_status::text,
               'body', left(m.body, 2000),
               'occurredAt', m.created_at,
               'subjectUserId', m.sender_id,
               'subjectUserName', sender.display_name,
               'counterpartyName', case when bk.client_id = m.sender_id
                                        then tasker.display_name else client.display_name end,
               'taskId', bk.task_id,
               'taskTitle', t.title,
               'bookingId', bk.id,
               'amountCentavos', null,
               'extra', jsonb_build_object(
                 'bookingStatus', bk.status::text,
                 'attachmentCount', (select count(*) from public.message_media mm
                                      where mm.message_id = m.id))
             )
        into v_subject
        from public.messages m
        join public.profiles sender on sender.id = m.sender_id
        join public.conversations cv on cv.id = m.conversation_id
        join public.bookings bk on bk.id = cv.booking_id
        join public.profiles client on client.id = bk.client_id
        join public.profiles tasker on tasker.id = bk.tasker_id
        join public.tasks t on t.id = bk.task_id
       where m.id = p_resource_id;

    when 'offer' then
      select jsonb_build_object(
               'exists', true,
               'kind', 'offer',
               'label', format('Offer by "%s" on task "%s"', tasker.display_name, t.title),
               'status', o.status::text,
               'body', left(o.message, 2000),
               'occurredAt', o.created_at,
               'subjectUserId', o.tasker_id,
               'subjectUserName', tasker.display_name,
               'counterpartyName', client.display_name,
               'taskId', t.id,
               'taskTitle', t.title,
               'bookingId', null,
               'amountCentavos', o.amount_centavos,
               'extra', jsonb_build_object('taskStatus', t.status::text)
             )
        into v_subject
        from public.offers o
        join public.profiles tasker on tasker.id = o.tasker_id
        join public.tasks t on t.id = o.task_id
        join public.profiles client on client.id = t.client_id
       where o.id = p_resource_id;

    when 'booking' then
      select jsonb_build_object(
               'exists', true,
               'kind', 'booking',
               'label', format('Booking between "%s" and "%s" for task "%s"',
                               client.display_name, tasker.display_name, t.title),
               'status', bk.status::text,
               'body', null,
               'occurredAt', bk.created_at,
               'subjectUserId', bk.tasker_id,
               'subjectUserName', tasker.display_name,
               'counterpartyName', client.display_name,
               'taskId', bk.task_id,
               'taskTitle', t.title,
               'bookingId', bk.id,
               'amountCentavos', bk.agreed_centavos,
               'extra', jsonb_build_object(
                 'clientId', bk.client_id,
                 'taskerId', bk.tasker_id,
                 'messageCount', (select count(*) from public.messages m
                                   join public.conversations cv on cv.id = m.conversation_id
                                  where cv.booking_id = bk.id))
             )
        into v_subject
        from public.bookings bk
        join public.profiles client on client.id = bk.client_id
        join public.profiles tasker on tasker.id = bk.tasker_id
        join public.tasks t on t.id = bk.task_id
       where bk.id = p_resource_id;

    else
      -- An unknown type is a data problem, not a caller problem: say so plainly
      -- rather than raising and blanking the whole case page.
      v_subject := jsonb_build_object(
        'exists', false, 'kind', p_resource_type,
        'label', format('Unsupported resource type "%s"', p_resource_type));
  end case;

  -- A reported task/message/user can be deleted after the case is filed. The page
  -- must still open and still allow a decision, so this is a normal outcome.
  return coalesce(v_subject, jsonb_build_object(
    'exists', false, 'kind', p_resource_type,
    'label', format('This %s no longer exists', p_resource_type)));
end;
$$;

comment on function app.case_subject_json(text, uuid) is
  'Resolves an Admin case subject from live app rows. Display names, statuses, '
  'amounts and aggregate counts only - never contact details or exact location.';

-- ---------------------------------------------------------------------------
-- Report subject: assignment-scoped, reasoned, audited once.
-- ---------------------------------------------------------------------------
create or replace function public.admin_read_report_subject(
  p_report_id uuid,
  p_reason text,
  p_idempotency_key text
)
returns jsonb
language plpgsql
security definer
set search_path = public, app
as $$
declare
  v_cap    user_capability;
  v_report public.reports;
begin
  perform app.assert_reasoned(p_reason, p_idempotency_key);
  if not app.admin_assigned_report(p_report_id) then
    raise exception 'FORBIDDEN: not the assigned Admin for this report.'
      using errcode = 'insufficient_privilege';
  end if;
  v_cap := app.acting_capability(array['ADMIN_SUPPORT','ADMIN_SUPER']::user_capability[]);
  perform app.audit_read_once('admin.read.report_subject', 'report', p_report_id,
                              v_cap, p_reason, p_idempotency_key);

  select * into v_report from public.reports where id = p_report_id;

  return app.case_subject_json(v_report.resource_type, v_report.resource_id)
      || jsonb_build_object(
           'resourceType', v_report.resource_type,
           'resourceId', v_report.resource_id,
           -- The reporter is disclosed to the ASSIGNED Admin only. Triage needs it:
           -- a single complaint and a coordinated pile-on look identical without it.
           'reporter', jsonb_build_object(
             'id', v_report.reporter_id,
             'displayName', (select display_name from public.profiles
                              where id = v_report.reporter_id),
             'accountStatus', (select account_status::text from public.profiles
                                where id = v_report.reporter_id),
             'reportsFiled', (select count(*) from public.reports r
                               where r.reporter_id = v_report.reporter_id),
             'reportsDismissed', (select count(*) from public.reports r
                                   where r.reporter_id = v_report.reporter_id
                                     and r.status = 'DISMISSED')),
           -- Distinct reporters on the SAME resource, as a count. Who else
           -- complained is not the assigned Admin's business; how many is.
           'resourceReportSummary', jsonb_build_object(
             'distinctReporters', (select count(distinct r.reporter_id) from public.reports r
                                    where r.resource_type = v_report.resource_type
                                      and r.resource_id = v_report.resource_id),
             'openCases', (select count(*) from public.reports r
                            where r.resource_type = v_report.resource_type
                              and r.resource_id = v_report.resource_id
                              and r.status in ('OPEN','TRIAGED')),
             'actionedCases', (select count(*) from public.reports r
                                where r.resource_type = v_report.resource_type
                                  and r.resource_id = v_report.resource_id
                                  and r.status = 'ACTIONED')));
end;
$$;

-- ---------------------------------------------------------------------------
-- Dispute subject: the booking, its parties, and the task it is about.
-- ---------------------------------------------------------------------------
create or replace function public.admin_read_dispute_subject(
  p_dispute_id uuid,
  p_reason text,
  p_idempotency_key text
)
returns jsonb
language plpgsql
security definer
set search_path = public, app
as $$
declare
  v_cap        user_capability;
  v_booking_id uuid;
begin
  perform app.assert_reasoned(p_reason, p_idempotency_key);
  if not app.admin_assigned_dispute(p_dispute_id) then
    raise exception 'FORBIDDEN: not the assigned Admin for this dispute.'
      using errcode = 'insufficient_privilege';
  end if;
  v_cap := app.acting_capability(array['ADMIN_FINANCE','ADMIN_SUPER']::user_capability[]);
  perform app.audit_read_once('admin.read.dispute_subject', 'dispute', p_dispute_id,
                              v_cap, p_reason, p_idempotency_key);

  select booking_id into v_booking_id from public.disputes where id = p_dispute_id;

  return app.case_subject_json('booking', v_booking_id)
      || jsonb_build_object('resourceType', 'booking', 'resourceId', v_booking_id);
end;
$$;

-- ---------------------------------------------------------------------------
-- ACLs.
--
-- Revoking from PUBLIC alone is NOT enough on Supabase: the project's default
-- privileges grant EXECUTE on new public functions to anon, authenticated and
-- service_role, so each role is revoked explicitly before the single intended
-- grant (the same pattern as `submit_report` in 0048).
--
-- service_role stays revoked deliberately: these functions are identity-scoped
-- through `auth.uid()`, so a service-role call could not be attributed to an
-- Admin and would produce an unattributable audit row.
-- ---------------------------------------------------------------------------
revoke all on function app.case_subject_json(text, uuid)
  from public, anon, authenticated, service_role;
revoke all on function public.admin_read_report_subject(uuid, text, text)
  from public, anon, authenticated, service_role;
revoke all on function public.admin_read_dispute_subject(uuid, text, text)
  from public, anon, authenticated, service_role;

grant execute on function public.admin_read_report_subject(uuid, text, text) to authenticated;
grant execute on function public.admin_read_dispute_subject(uuid, text, text) to authenticated;


-- ===================================================================
-- 0050_report_outcome_notification.sql
-- ===================================================================

-- 0050_report_outcome_notification.sql
-- Tell the reporter what happened to their report.
--
-- `submit_report` (0048) gave the reports queue a producer and `admin_read_report_subject`
-- (0049) made the queue triageable, but the loop still ended in silence: an Admin
-- moved a report to ACTIONED or DISMISSED and the person who filed it was never
-- told. For a trust & safety flow that is the worst place to go quiet — a user who
-- reports harassment and hears nothing reasonably concludes nobody looked.
--
-- Two changes, both narrow:
--   1. `REPORT_RESOLVED` is mapped to the existing `system` preference category.
--   2. `admin_transition_report` notifies the reporter on TERMINAL statuses only.
--
-- What the notification deliberately does NOT say: what action was taken, against
-- whom, or any detail about the other party. "We reviewed it and acted" is the
-- honest limit of what a reporter is entitled to know about someone else's account.
--
-- The reported user is NOT notified. There is no defined content-removal or
-- account-restriction consequence in the product yet (blocking remains policy-
-- blocked under D13/11.5), so a message telling someone they were reported would
-- describe an outcome that does not exist.

-- ---------------------------------------------------------------------------
-- Preference category.
--
-- Restated in full: `app.notification_category` is an immutable SQL function, so
-- there is no partial replacement. `REPORT_RESOLVED` is listed explicitly rather
-- than left to the `else` branch — relying on the fallback would make a future
-- rename silently change the category a user's toggle controls.
--
-- `system` rather than a new `safety` toggle: it is the existing home for
-- platform/administrative messages, and adding a category means adding a switch to
-- the mobile preferences screen for exactly one event type.
-- ---------------------------------------------------------------------------
create or replace function app.notification_category(p_type text)
returns text
language sql
immutable
as $$
  select case p_type
    when 'OFFER_RECEIVED'         then 'offers'
    when 'OFFER_SELECTED'         then 'offers'
    when 'PAYMENT_CONFIRMED'      then 'payments'
    when 'PAYMENT_FAILED'         then 'payments'
    when 'BOOKING_STARTED'        then 'bookings'
    when 'COMPLETION_REQUESTED'   then 'bookings'
    when 'COMPLETION_REMINDER'    then 'bookings'
    when 'BOOKING_COMPLETED'      then 'bookings'
    when 'DISPUTE_OPENED'         then 'disputes'
    when 'REVIEW_RECEIVED'        then 'reviews'
    when 'REVIEW_REMINDER'        then 'reviews'
    when 'MESSAGE_RECEIVED'       then 'messages'
    when 'VERIFICATION_DECISION'  then 'verification'
    when 'NEARBY_TASK'            then 'nearby'
    when 'REPORT_RESOLVED'        then 'system'
    else 'system'
  end;
$$;

-- ---------------------------------------------------------------------------
-- Report transition, now closing the loop with the reporter.
--
-- Restated in full from 0013 with one added block. Everything else is unchanged:
-- assigned-Admin-only, reasoned, idempotent by (admin, action, key), the same
-- allowed transition set, and both a `moderation_actions` and an `audit_logs` row.
-- ---------------------------------------------------------------------------
create or replace function public.admin_transition_report(
  p_report_id uuid, p_to_status report_status, p_reason text, p_idempotency_key text
)
returns public.reports
language plpgsql
security definer
set search_path = public, app
as $$
declare
  v_row public.reports;
  v_cap user_capability;
  v_from report_status;
begin
  perform app.assert_reasoned(p_reason, p_idempotency_key);
  v_cap := app.acting_capability(array['ADMIN_SUPPORT','ADMIN_SUPER']::user_capability[]);
  if v_cap is null then
    raise exception 'FORBIDDEN: requires an active support/super Admin.' using errcode = 'insufficient_privilege';
  end if;

  select * into v_row from public.reports where id = p_report_id for update;
  if not found then raise exception 'NOT_FOUND: report' using errcode = 'no_data_found'; end if;
  if v_row.assignee_id is distinct from auth.uid() then
    raise exception 'FORBIDDEN: only the assigned Admin may transition this report.'
      using errcode = 'insufficient_privilege';
  end if;

  -- Idempotent replay or already at the target status. Returning early here is
  -- also what keeps the reporter from being notified twice about one decision.
  if v_row.status = p_to_status
     or exists (select 1 from public.moderation_actions ma
                where ma.resource_type = 'report' and ma.resource_id = p_report_id
                  and ma.action = 'transition:' || p_to_status::text and ma.admin_id = auth.uid()
                  and ma.metadata->>'idempotency_key' = p_idempotency_key) then
    return v_row;
  end if;

  v_from := v_row.status;
  if not ((v_from::text || '>' || p_to_status::text) = any (array[
        'OPEN>TRIAGED', 'OPEN>DISMISSED',
        'TRIAGED>ACTIONED', 'TRIAGED>DISMISSED'])) then
    raise exception 'INVALID_STATE: report transition %->% is not allowed.', v_from, p_to_status
      using errcode = 'check_violation';
  end if;

  update public.reports set status = p_to_status, updated_at = now()
    where id = p_report_id returning * into v_row;

  insert into public.moderation_actions (admin_id, capability, resource_type, resource_id, action, reason, metadata)
  values (auth.uid(), v_cap, 'report', p_report_id, 'transition:' || p_to_status::text, p_reason,
          jsonb_build_object('idempotency_key', p_idempotency_key, 'from', v_from, 'to', p_to_status));
  insert into public.audit_logs (actor_id, action, resource_type, resource_id, safe_metadata)
  values (auth.uid(), 'admin.transition.report', 'report', p_report_id,
          jsonb_build_object('capability', v_cap, 'from', v_from, 'to', p_to_status,
                             'idempotency_key', p_idempotency_key));

  -- Terminal outcomes only. TRIAGED is an internal queue step; telling a reporter
  -- "your report changed to TRIAGED" leaks how the queue works and says nothing
  -- they can use. The Admin's private `reason` is never forwarded.
  if p_to_status in ('ACTIONED', 'DISMISSED')
     -- An Admin who reported something and then handled it themselves does not
     -- need a notification about their own decision.
     and v_row.reporter_id is distinct from auth.uid() then
    perform app.notify(
      v_row.reporter_id,
      'REPORT_RESOLVED',
      case p_to_status
        when 'ACTIONED' then 'We acted on your report'
        else 'We reviewed your report'
      end,
      case p_to_status
        when 'ACTIONED' then
          'Thanks for reporting this. Our team reviewed it and has taken action. '
          || 'We cannot share details about another person''s account.'
        else
          'Our team reviewed your report and did not find a policy breach this time. '
          || 'If something new happens, report it again and we will take another look.'
      end,
      'report',
      p_report_id
    );
  end if;

  return v_row;
end;
$$;

